def _send_dc_iv_curve(ui_setting, selected_dc, silent=False):
    """从指定直流设置页读取 IV 四点并下发到对应 DC 通道。"""
    global dc1_controller, dc2_controller, dc3_controller, dc4_controller

    controller_map = {
        "DC1": ("0", 0),
        "DC2": ("1", 1),
        "DC3": ("2", 2),
        "DC4": ("3", 3),
    }

    if selected_dc not in controller_map:
        _show_connect_message("请选择有效的直流电源（DC1~DC4）", ui_setting)
        return []

    dc_key, dc_index = controller_map[selected_dc]
    controller = {
        "DC1": dc1_controller,
        "DC2": dc2_controller,
        "DC3": dc3_controller,
        "DC4": dc4_controller,
    }[selected_dc]
    if controller is None:
        controller = DCController(
            logger,
            _show_connect_message,
            now_to_datenow,
            ui_setting=ui_setting,
            rm=rm,
            configure_scpi_resource=_configure_scpi_resource,
        )
        if selected_dc == "DC1":
            dc1_controller = controller
        elif selected_dc == "DC2":
            dc2_controller = controller
        elif selected_dc == "DC3":
            dc3_controller = controller
        else:
            dc4_controller = controller

    if controller.handle is None:
        _show_connect_message(f"{selected_dc}未连接，请先连接{selected_dc}设备", ui_setting)
        return []

    order_list = send_dc_test_message(
        controller.handle,
        ui_setting,
        per_dc_factor,
        command_list_DC,
        DCGetIVValueFunction,
        logger,
        now_to_datenow,
        dc_index=dc_index,
        dc_label=selected_dc,
        silent=silent,
    )
    if not order_list:
        return []

    dc_vendor = per_dc_factor.get(dc_key, "")
    try:
        from utils.instrument_catalog_bootstrap import refresh_command_list_dc

        _dc_list = refresh_command_list_dc()
    except Exception:
        _dc_list = command_list_DC
    order_list.extend(_dc_list.get(dc_vendor, []))

    for command in order_list:
        try:
            controller.write_command(command, label=selected_dc)
        except Exception as e:
            strtimenow = now_to_datenow()
            _dc_log = _format_dc_cmd_for_log(command)
            logger.info(f"Send message {_dc_log} to {selected_dc} error :{e}")
            print(f"{strtimenow} Send message {_dc_log} to {selected_dc} error :{e}")
            _show_connect_message(f"{selected_dc}参数下发失败：{e}", ui_setting)
            return []
        else:
            strtimenow = now_to_datenow()
            _dc_log = _format_dc_cmd_for_log(command)
            logger.info(f"SendMessageTo{selected_dc}:{_dc_log}")
            print(strtimenow + f"SendMessageTo{selected_dc}:{_dc_log}")
            if hasattr(ui_setting, "textEdit_ReturnMessage"):
                ui_setting.textEdit_ReturnMessage.append(
                    f"SendMessageTo{selected_dc}:{_dc_log}"
                )
        time.sleep(0.8)

    return order_list


