def _toggle_connection_button(connected_button_name, connected):
    btn = getattr(ui, connected_button_name, None)
    if btn is not None:
        btn.setText("取消连接" if connected else "连接设备")


def _save_device_status(device_name, connected, resource="", extra=None):
    """更新 status.json 中的设备连接状态，刷新首页显示。"""
    import json
    import os
    from utils.status_json_devices import apply_device_connection, empty_status_payload

    _status_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "status.json")
    try:
        with open(_status_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        data = empty_status_payload()
    if not isinstance(extra, dict):
        try:
            dn = str(device_name or "").strip()
            if dn in ("交流电源", "交流源"):
                extra = _ac_status_extra()
            elif dn.startswith("直流电源") or dn.startswith("直流源"):
                extra = _dc_status_extra(dn)
            elif dn == "DEWETRON":
                extra = _dewetron_status_extra()
        except Exception:
            extra = None
    data = apply_device_connection(
        data,
        device_name=device_name,
        connected=bool(connected),
        resource=resource or "",
        extra=extra if isinstance(extra, dict) else None,
    )
    with open(_status_file, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    # 刷新首页（任意线程：由 _reload_home_status 投递到 UI，勿在此碰 QWidget）
    if hasattr(ui, '_home_dots') and hasattr(ui, 'stackedWidget'):
        _reload_home_status(data)



def _widget_plain(widget) -> str:
    if widget is None:
        return ""
    try:
        if hasattr(widget, "toPlainText"):
            return str(widget.toPlainText() or "").strip()
        if hasattr(widget, "currentText"):
            return str(widget.currentText() or "").strip()
        if hasattr(widget, "text"):
            return str(widget.text() or "").strip()
    except Exception:
        return ""
    return ""


def _dc_brand_raw(idx: int) -> str:
    """当前直流槽位品牌：连接后的 per_dc_factor，否则面包屑设备类型。"""
    factors = globals().get("per_dc_factor") or {}
    raw = factors.get(str(idx))
    if raw is None:
        raw = factors.get(idx)
    text = str(raw or "").strip()
    if text:
        return text
    type_names = ("_dc1_device_type", "_dc2_device_type", "_dc3_device_type", "_dc4_device_type")
    if 0 <= int(idx) < len(type_names):
        return str(globals().get(type_names[int(idx)]) or "").strip()
    return ""


def _read_dc1_bluesight_page():
    """蓝点 DC1 页当前模式和数值。没有该页时返回 None。"""
    ref = globals().get("_dc1_bs_ref")
    if not isinstance(ref, dict):
        return None
    try:
        mode_idx = int(ref["combo_mode"].currentIndex())
    except Exception:
        return None
    page = {"mode": "sas" if mode_idx == 1 else "original"}
    try:
        page["pmpp_kw"] = float(ref["sp_pmpp"].value())
        page["umpp_v"] = float(ref["sp_umpp"].value())
        page["ff"] = float(ref["sp_ff"].value())
    except Exception:
        pass
    if mode_idx != 0:
        return page
    try:
        idx_o = int(ref["combo_outmode"].currentIndex())
        names = ("cv", "cc", "cp", "cr")
        page["outmode"] = names[idx_o] if 0 <= idx_o < len(names) else "cv"
        from PyQt5.QtWidgets import QDoubleSpinBox

        spins = ref["params_stack"].widget(idx_o).findChildren(QDoubleSpinBox)
        vals = []
        for spin in spins:
            try:
                vals.append(float(spin.value()))
            except Exception:
                continue
        if page["outmode"] == "cv" and vals:
            page["voltage_v"] = vals[0]
        elif page["outmode"] == "cc" and vals:
            page["current_a"] = vals[0]
        elif page["outmode"] == "cp" and vals:
            page["power_kw"] = vals[0]
    except Exception:
        pass
    return page


def _read_dc1_itech_iv():
    ref = globals().get("_dc1_itech_ref")
    if not isinstance(ref, dict):
        return {}
    return {
        "vmp": _widget_plain(ref.get("textEdit_Vmp")),
        "voc": _widget_plain(ref.get("textEdit_Voc")),
        "imp": _widget_plain(ref.get("textEdit_Imp")),
        "isc": _widget_plain(ref.get("textEdit_Isc")),
        "pf": _widget_plain(ref.get("textEdit_PF")),
    }


def _ac_status_extra():
    """交流源当前品牌页的电压/频率写入 status.json。爱科不读致茂页。"""
    try:
        from utils.status_json_devices import ac_connection_extra, canonical_reported_brand

        brand = canonical_reported_brand(str(globals().get("_ac_current_brand") or ""))
        if brand == "itech":
            ref = globals().get("_ac_itch_ref")
            ref = ref if isinstance(ref, dict) else {}
            return ac_connection_extra(
                brand="itech",
                voltage=_widget_plain(ref.get("textEdit_VOLT")),
                frequency=_widget_plain(ref.get("textEdit_FR")),
                phase=_widget_plain(ref.get("combo_phase")),
            )
        ui_ac = globals().get("uiACSetting")
        phase = _widget_plain(getattr(ui_ac, "comboBox_Phase", None) if ui_ac is not None else None)
        return ac_connection_extra(
            brand=brand or "chroma",
            voltage=_widget_plain(getattr(ui_ac, "textEdit_AC_VOLT", None) if ui_ac is not None else None),
            frequency=_widget_plain(getattr(ui_ac, "textEdit_AC_FR", None) if ui_ac is not None else None),
            phase=phase,
        )
    except Exception:
        return {"measures": {}}


def _dc_status_extra(device_name="直流电源1"):
    """直流源当前品牌页 IV + 额定电流上限。蓝点读蓝点页，不拿致茂/爱科默认值。"""
    try:
        from utils.status_json_devices import (
            bluesight_iv_fields,
            canonical_reported_brand,
            dc_connection_extra,
            read_dc_ui_snapshot,
        )

        name = str(device_name or "")
        slot = "dc1"
        ui_name = "uiDC1Setting"
        idx = 0
        if "2" in name:
            slot, ui_name, idx = "dc2", "uiDC2Setting", 1
        elif "3" in name:
            slot, ui_name, idx = "dc3", "uiDC3Setting", 2
        elif "4" in name:
            slot, ui_name, idx = "dc4", "uiDC4Setting", 3
        brand = canonical_reported_brand(_dc_brand_raw(idx))
        if brand == "bluesight":
            page = _read_dc1_bluesight_page() if idx == 0 else None
            iv = bluesight_iv_fields(page or {})
            snap = dc_connection_extra(brand=brand, iv=iv, slot=slot, force_iv=True)
        elif brand == "itech" and idx == 0:
            snap = dc_connection_extra(
                brand=brand, iv=_read_dc1_itech_iv(), slot=slot, force_iv=True
            )
        else:
            ui_snap = read_dc_ui_snapshot(globals().get(ui_name), slot=slot)
            measures = ui_snap.get("measures") if isinstance(ui_snap, dict) else {}
            measures = measures if isinstance(measures, dict) else {}
            iv = {
                "vmp": measures.get("vmp") or "",
                "voc": measures.get("voc") or "",
                "imp": measures.get("imp") or "",
                "isc": measures.get("isc") or "",
                "pf": measures.get("powerPercent") or "",
            }
            snap = dc_connection_extra(brand=brand or "chroma", iv=iv, slot=slot)
        if not isinstance(snap, dict):
            snap = {"measures": {}}
        try:
            arr = globals().get("ArrayfDCCurrValue") or []
            if idx < len(arr):
                lim = float(arr[idx])
                if lim > 0:
                    measures = dict(snap.get("measures") or {}) if isinstance(snap.get("measures"), dict) else {}
                    measures["curr_max"] = lim
                    snap["measures"] = measures
                    snap["curr_max"] = lim
        except (TypeError, ValueError, IndexError):
            pass
        return snap
    except Exception:
        return {"measures": {}}


def _sync_experiment_dc_from_bluesight_curve(pmpp_kw, umpp_v, ff) -> None:
    """SAS 曲线下发成功后，把换算的四点写进实验对话框，并推到当前 IOT 实验。"""
    from utils.bluesight_experiment_iv import (
        apply_experiment_dc1_to_open_widgets,
        experiment_dc1_widgets,
    )
    from utils.status_json_devices import bluesight_iv_fields

    iv = bluesight_iv_fields(
        {"mode": "sas", "pmpp_kw": pmpp_kw, "umpp_v": umpp_v, "ff": ff}
    )
    fields = experiment_dc1_widgets(iv)
    if not fields:
        return
    written = apply_experiment_dc1_to_open_widgets(iv)
    try:
        ctrl = globals().get("dc1_controller")
        connected = ctrl is not None and getattr(ctrl, "connected", False)
        resource = ""
        if connected:
            resource = str(getattr(ctrl, "resource", "") or "")
        _save_device_status(
            "直流电源1",
            bool(connected),
            resource,
            extra=_dc_status_extra("直流电源1"),
        )
    except Exception as exc:
        print(f"[DC1 Bluesight] 刷新直流状态跳过: {exc}", flush=True)
    msg = (
        f"[DC1 Bluesight] 实验直流源已同步 Vmp={fields.get('textEdit_S1_DC1_VOLT')} "
        f"Imp={fields.get('textEdit_S1_DC1_CURR')} "
        f"Voc={fields.get('textEdit_S1_DC1_Voc')} "
        f"Isc={fields.get('textEdit_S1_DC1_Isc')} "
        f"（写了 {written} 个控件）"
    )
    print(msg, flush=True)
    try:
        ui.textEdit_ReturnMessage.append(msg)
    except Exception:
        pass

    def _push():
        try:
            from utils.iot_local_run import _build_client

            client = _build_client()
            client.sync_dc1_widgets(fields)
        except Exception as exc:
            print(f"[DC1 Bluesight] 同步 IOT 实验直流源跳过: {exc}", flush=True)

    import threading

    threading.Thread(target=_push, daemon=True, name="bluesight-dc-sync").start()


def _refresh_dc_curr_max_status(dc_index=None):
    """ArrayfDCCurrValue 变更后刷新 status.json，供 Agent/IOT 读到工控机实际电流上限。"""
    names = ("直流电源1", "直流电源2", "直流电源3", "直流电源4")
    ctrls = (
        globals().get("dc1_controller"),
        globals().get("dc2_controller"),
        globals().get("dc3_controller"),
        globals().get("dc4_controller"),
    )
    idxs = range(4) if dc_index is None else (int(dc_index),)
    for i in idxs:
        if i < 0 or i >= 4:
            continue
        ctrl = ctrls[i]
        if ctrl is None or not getattr(ctrl, "connected", False):
            continue
        try:
            _save_device_status(names[i], True, "", extra=_dc_status_extra(names[i]))
        except Exception as exc:
            print(f"[DC上限] 刷新 status 失败 DC{i + 1}: {exc}", flush=True)


def _sync_array_dc_curr_from_device(dc_index: int) -> None:
    """从已连直流源读回 OCP/电流上限，写入 ArrayfDCCurrValue（覆盖默认 15.75）。"""
    global ArrayfDCCurrValue
    if not (0 <= int(dc_index) < 4):
        return
    ctrls = (
        globals().get("dc1_controller"),
        globals().get("dc2_controller"),
        globals().get("dc3_controller"),
        globals().get("dc4_controller"),
    )
    ctrl = ctrls[int(dc_index)]
    if ctrl is None:
        return
    brand = None
    try:
        factors = globals().get("per_dc_factor") or {}
        brand = factors.get(str(dc_index)) or factors.get(dc_index)
    except Exception:
        brand = None
    try:
        from utils.iot_brand_limit_read import read_dc_output_limits

        lim = read_dc_output_limits(ctrl, brand)
        if not isinstance(lim, dict) or lim.get("_unread"):
            return
        cm = lim.get("curr_max")
        if cm is None:
            return
        val = float(cm)
        if val <= 0:
            return
        # Chroma Soft Panel 双台并联：OCP 寄存器常仍是单机 15.75，按 MSTSLV 抬到 31.5
        try:
            brand_s = str(brand or "").strip().lower()
            if "chroma" in brand_s or brand_s in ("", "none", "null"):
                from utils.chroma_soft_panel_limits import probe_and_scale_limits

                handle = getattr(ctrl, "handle", None)
                scaled, _pw, units = probe_and_scale_limits(handle)
                if units > 1:
                    val = max(val, scaled)
        except Exception as _mst_exc:
            print(f"[DC上限] DC{int(dc_index) + 1} 主从缩放跳过: {_mst_exc}", flush=True)
        if not isinstance(ArrayfDCCurrValue, list) or len(ArrayfDCCurrValue) < 4:
            ArrayfDCCurrValue = [15.75, 15.75, 15.75, 15.75]
        ArrayfDCCurrValue[int(dc_index)] = val
        try:
            from utils.app_context import get_app_context

            ctx = get_app_context()
            if ctx is not None:
                ctx.ArrayfDCCurrValue = ArrayfDCCurrValue
        except Exception:
            pass
        print(f"[DC上限] DC{int(dc_index) + 1} 读回 curr_max={val}", flush=True)
    except Exception as exc:
        print(f"[DC上限] DC{int(dc_index) + 1} 读回失败: {exc}", flush=True)


def _resolve_soft_panel_curr_limit(handle, planned: float) -> float:
    """Soft Panel 写 :sour:curr:prot:high max 后读回真实上限。"""
    from utils.chroma_soft_panel_limits import resolve_curr_limit_after_max

    return resolve_curr_limit_after_max(handle, planned)


