        total_rounds = int(state.get("total_rounds") or 0)
        cmd_index = int(state.get("cmd_index") or 0)
        cmd_total = int(state.get("cmd_total") or 0)
        summary = f"试验进度：{project or '-'} | {status} | {progress}%"
