#ramp解析函数
def RampCommand(strCommand,strRampFirstValue,strRampEndValue,strRampTimes):
    #global strArrayRampCommand
    fRampFirstValue = float(strRampFirstValue)
    fRampEndValue = float(strRampEndValue)
    iRampTimes = int(strRampTimes)

    fRampValue = fRampFirstValue-fRampEndValue
    iRampTimesSingle = iRampTimes -1
    iRampStep = fRampValue/iRampTimesSingle
    iRampStep = round(iRampStep,2)
    strArrayRampValue = ['' for i in range(iRampTimes)]

    strArrayRampValue[0] = fRampFirstValue

    for x in range(iRampTimesSingle):
        strArrayRampValue[x+1] = round(strArrayRampValue[x]-iRampStep,2)

    strArrayRampCommand = ['' for i in range(len(strArrayRampValue))]
    for xx in range(len(strArrayRampCommand)):
        strArrayRampCommand[xx] = strCommand + ' ' + str(strArrayRampValue[xx])

    return strArrayRampCommand

