def _snapshot_dewetron_append(project_name):
    """Capture list/state boundaries before one eligible project's Send call."""
    global strSettingTestFlag
    section = _get_dewetron_section(project_name)
    if section is None:
        return None
    config = section.get_dewetron_config()
    overwrite = strAddTestFlag == "0"
    previous_setting_flag = strSettingTestFlag
    # Every Send sets this flag on success. Clear first so a failed validation
    # cannot look like success from a prior append (WT / DEW 同理).
    strSettingTestFlag = "0"
    return {
        'project_name': project_name,
        'segment_start': 0 if overwrite else len(strArrayTest),
        'program_start': 0 if overwrite else len(test_program),
        'config': config,
        'previous_setting_flag': previous_setting_flag,
        'fingerprint': config_fingerprint(
            config,
            test_type=get_project_spec(project_name).test_type,
            profile=get_project_spec(project_name).profile,
        ),
    }


def _normalize_generated_dewetron_rows(project_name, snapshot):
    """Convert the newly appended rows to an executor-compatible DEW segment."""
    global strArrayTest, test_program, WT_is_checked, project_change, strSettingTestFlag
    if not snapshot or not _is_dewetron_project_mode(project_name):
        return True

    if strSettingTestFlag != "1":
        del strArrayTest[snapshot['segment_start']:]
        del test_program[snapshot['program_start']:]
        strSettingTestFlag = snapshot['previous_setting_flag']
        ui.textEdit_ReturnMessage.append(f"[{project_name}] 命令校验失败，已回滚本次追加")
        return False

    section = _get_dewetron_section(project_name)
    config = section.get_dewetron_config()
    errors = config.validation_errors(require_export_fields=True)
    if errors:
        for error in errors:
            ui.textEdit_ReturnMessage.append(f"[DEWETRON] {error}")
        del strArrayTest[snapshot['segment_start']:]
        del test_program[snapshot['program_start']:]
        strSettingTestFlag = snapshot['previous_setting_flag']
        return False

    fingerprint = config_fingerprint(
        config,
        test_type=get_project_spec(project_name).test_type,
        profile=get_project_spec(project_name).profile,
    )
    if (
        getattr(section, '_dew_config_dirty', True)
        or getattr(section, '_dew_applied_fingerprint', None) != fingerprint
    ):
        if not _ensure_dewetron_config_applied(project_name, silent=True):
            ui.textEdit_ReturnMessage.append("[DEWETRON] 配置已变更，请先点击测试生效")
            del strArrayTest[snapshot['segment_start']:]
            del test_program[snapshot['program_start']:]
            strSettingTestFlag = snapshot['previous_setting_flag']
            return False
        fingerprint = config_fingerprint(
            config,
            test_type=get_project_spec(project_name).test_type,
            profile=get_project_spec(project_name).profile,
        )
        if (
            getattr(section, '_dew_config_dirty', True)
            or getattr(section, '_dew_applied_fingerprint', None) != fingerprint
        ):
            ui.textEdit_ReturnMessage.append("[DEWETRON] 配置已变更，请先点击测试生效")
            del strArrayTest[snapshot['segment_start']:]
            del test_program[snapshot['program_start']:]
            strSettingTestFlag = snapshot['previous_setting_flag']
            return False
    remembered = getattr(section, '_dew_append_fingerprint', None)
    if remembered is not None and remembered != fingerprint:
        ui.textEdit_ReturnMessage.append("[DEWETRON] 追加配置已变化，请重置计数后重新追加")
        del strArrayTest[snapshot['segment_start']:]
        del test_program[snapshot['program_start']:]
        strSettingTestFlag = snapshot['previous_setting_flag']
        return False

    generated = [coerce_command_row(row) for row in strArrayTest[snapshot['segment_start']:]]
    normalized = []
    from utils.dewetron_recording import make_acq_start_row, make_acq_stop_row

    for row in generated:
        device = str(row[0]).strip().upper()
        if device in WT_ONLY_DEVICES:
            trigger_waits = []
            for column in COMMAND_WT_TRIGGER_COLUMNS:
                if row[column] not in ('', None):
                    try:
                        trigger_waits.append(int(row[column]))
                    except (TypeError, ValueError):
                        pass
            if trigger_waits:
                normalized.append(make_wait_row(max(trigger_waits)))
            continue
        if device == 'AC' and str(row[1]).strip().lower() == 'wait' and row[9] == 3000:
            # This row exists only to switch WTViewer projects between appends.
            continue
        clean = list(row)
        marker = ""
        if len(clean) > 6 and clean[6] not in ('', None):
            marker = str(clean[6]).strip().upper()
        # 与 WT 连续录对齐：ASYNC_START/WAIT_END → 德威创 START/STOP（勿整段最前插入）
        if marker in ("ASYNC_START", "WT_ASYNC_START"):
            for column in COMMAND_WT_TRIGGER_COLUMNS:
                if column < len(clean):
                    clean[column] = ''
            normalized.append(make_acq_start_row())
            continue
        if marker == "WAIT_END":
            for column in COMMAND_WT_TRIGGER_COLUMNS:
                if column < len(clean):
                    clean[column] = ''
            normalized.append(make_acq_stop_row())
            continue
        trigger_waits = []
        for column in COMMAND_WT_TRIGGER_COLUMNS:
            if clean[column] not in ('', None):
                try:
                    trigger_waits.append(int(clean[column]))
                except (TypeError, ValueError):
                    pass
                clean[column] = ''
        normalized.append(clean)
        if trigger_waits:
            # Preserve the configured dwell without invoking WTViewer automation.
            normalized.append(make_wait_row(max(trigger_waits)))

    project_ui = _dewetron_project_ui(project_name)
    from utils.matrix_recording_commands import get_record_mode
    from utils.wt_recording_mode import MODE_CONTINUOUS
    from utils.dewetron_recording import (
        apply_dewetron_recording_boundaries,
        resolve_dewetron_save_paths,
    )

    continuous = True
    file_names = []
    try:
        continuous = get_record_mode(project_ui) == MODE_CONTINUOUS
    except Exception:
        continuous = True
    try:
        file_names = _parse_progress_file_names()
    except Exception:
        file_names = []
    if project_name == "重连" and project_ui is not None:
        try:
            from utils.reconnect_commands import recommended_reconnect_names
            from utils.wt_recording_mode import MODE_SPLIT as _MODE_SPLIT

            mode = MODE_CONTINUOUS if continuous else _MODE_SPLIT
            recommended = recommended_reconnect_names(project_ui, mode)
            if recommended:
                file_names = list(recommended)
        except Exception:
            pass
    if project_name == "谐波电流" and project_ui is not None:
        try:
            from utils.wt_recording_mode import (
                MODE_SPLIT as _MODE_SPLIT,
                collect_harmonic_power_percents,
                harmonic_recommended_filenames,
            )

            mode = MODE_CONTINUOUS if continuous else _MODE_SPLIT
            recommended = harmonic_recommended_filenames(
                collect_harmonic_power_percents(project_ui), mode
            )
            if recommended:
                file_names = list(recommended)
        except Exception:
            pass
    if not file_names and continuous:
        try:
            from utils.wt_recording_mode import resolve_continuous_filename

            single = resolve_continuous_filename(project_ui)
            if single:
                file_names = [single]
        except Exception:
            pass

    normalized = apply_dewetron_recording_boundaries(
        normalized, continuous=continuous
    )
    # 兜底：规范化后仍缺启停则强制补齐（防止空 CSV）
    from utils.dewetron_recording import ensure_dewetron_acq_boundaries

    before_n = len(normalized)
    normalized = ensure_dewetron_acq_boundaries(normalized)
    if len(normalized) != before_n:
        ui.textEdit_ReturnMessage.append(
            f"[{project_name}] DEWETRON 已补齐缺失的 START/STOP 边界"
        )
    spec = get_project_spec(project_name)
    test_type = spec.test_type if spec else project_name
    file_names = _finalize_recording_file_names(file_names)
    dew_save_dir = ""
    try:
        dew_save_dir = str(getattr(config, "save_dir", "") or "").strip()
    except Exception:
        dew_save_dir = ""
    if not dew_save_dir:
        try:
            dew_save_dir = str(
                section.dewetron_panel.get_config().save_dir or ""
            ).strip()
        except Exception:
            dew_save_dir = ""
    save_paths = resolve_dewetron_save_paths(
        test_type=str(test_type or "dewetron"),
        continuous=continuous,
        file_names=file_names,
        base_dir=dew_save_dir or None,
    )
    section._dew_record_continuous = continuous
    section._dew_save_paths = list(save_paths)
    section._dew_save_index = 0
    section._dew_file_names = list(file_names) if file_names else [
        f"轮次{i + 1}" for i in range(len(save_paths))
    ]

    strArrayTest[snapshot['segment_start']:] = normalized
    del test_program[snapshot['program_start']:]
    WT_is_checked = ''
    project_change = ''
    section._dew_append_fingerprint = fingerprint
    mode_label = "一条线连续录" if continuous else "分开录/分文件"
    ui.textEdit_ReturnMessage.append(
        f"[{project_name}] DEWETRON模式已生成 {len(normalized)} 条命令"
        f"（{mode_label}，{len(save_paths)} 个文件，含 START/STOP）"
    )
    return True


def _reset_dewetron_append_fingerprint(project_name):
    section = _get_dewetron_section(project_name)
    if section is not None:
        section._dew_append_fingerprint = None
        section._dew_config_dirty = True
        section._dew_applied_fingerprint = None


def reset_wt_automation_state():
    """提交设定后重置WT自动化状态，确保下次开始会重新走自动化配置。"""
    global first_test, setting_status, messure_status, messsure_deatil_cofig, messure_project_cofig, WT_auto_messure_status
    global strTestStatusFlag
    # 仅在实际执行中（已触发启动或仍有待执行命令）时拒绝重置。
    # 自然结束后 strTestStatusFlag 可能仍短暂为「运行」但 strArrayTest 已空，
    # 此时必须允许重置，否则换项追加会跳过 wt_is_check / WT 宏脚本。
    if globals().get("strTestStatusFlag") == "运行":
        pending_start = globals().get("strTestFlag") == "1"
        has_commands = bool(globals().get("strArrayTest"))
        if pending_start or has_commands:
            _append_debug_log(
                "[state_guard][skip] reset_wt_automation_state ignored because test is running"
            )
            return
    first_test = ''
    setting_status = ''
    messure_status = ''
    messsure_deatil_cofig = ''
    messure_project_cofig = ''
    WT_auto_messure_status = ''

