#德国电压闪变
def thaidianyashanbianAppend():
    global strAddTestFlag, flicker_append_count, project_change, project_now
    if 'flicker_append_count' not in globals():
        flicker_append_count = 0
    from utils.append_mode import apply_append_mode, begin_append_attempt, commit_append_if_success
    _flag, _chg, mode = apply_append_mode(
        globals(), project_name='电压闪变', local_count=flicker_append_count
    )
    strAddTestFlag, project_change = _flag, _chg
    ui.textEdit_ReturnMessage.append(f"[闪变] 第{flicker_append_count + 1}次{mode}模式，开始生成命令...")
    _prev_setting = begin_append_attempt(globals())
    thaidianyashanbianSend()
    commit_append_if_success(globals(), '电压闪变', _prev_setting)

def thaidianyashanbianSend():
    global uiThaiDianYaShanBian,strArrayTest,dialog_windowTdianyashanbian
    global strSettingTestFlag, strArrayTestStep
    global strAddTestFlag, flicker_is_test
    global command_save_file_path, flicker_append_count
    if 'flicker_append_count' not in globals():
        flicker_append_count = 0

    # ── 德威创模式标记 ──
    is_dewetron = hasattr(uiThaiDianYaShanBian, '_mode') and uiThaiDianYaShanBian._mode == 'dewetron'

    def _get_wait_seconds(str_array_single):
        """提取单条命令的等待时间（秒）。

        注意：strArrayTest 的等待字段 [8]/[9] 在 RunProject 中是按 0.1 秒计数解释的。
        """
        wait_values = []
        for idx in (8, 9):
            if idx < len(str_array_single):
                value = str_array_single[idx]
                if value == "" or value is None:
                    continue
                try:
                    wait_values.append(float(value))
                except (ValueError, TypeError):
                    pass
        # 0.1 秒计数 -> 秒
        return (max(wait_values) * 0.1) if wait_values else 0.0

    def _append_cycle_padding(step_commands, cycle_seconds=600):
        """将单轮闪变步骤补齐到固定周期（默认10分钟）"""
        used_seconds = 0.0
        for command in step_commands:
            used_seconds += _get_wait_seconds(command)
        remain_seconds = int(max(0.0, cycle_seconds - used_seconds))
        if remain_seconds > 0:
            str_array_single = ["" for _ in range(10)]
            str_array_single[0] = "AC"
            str_array_single[1] = "query"
            str_array_single[2] = "*IDN?"
            # 秒 -> 0.1 秒计数
            str_array_single[8] = int(remain_seconds * 10)
            strArrayTest.append(str_array_single)
            step_commands.append(str_array_single)

    # IOT handoff 写入的国家标准（泰/欧等）；影响周期补齐与日志
    _flicker_std = str(getattr(uiThaiDianYaShanBian, "_solar_standard", "") or "").strip()
    _flicker_cycle = getattr(uiThaiDianYaShanBian, "_flicker_cycle_sec", None)
    try:
        _flicker_cycle = int(_flicker_cycle) if _flicker_cycle not in (None, "") else 600
    except (TypeError, ValueError):
        _flicker_cycle = 600
    if _flicker_std:
        try:
            ui.textEdit_ReturnMessage.append(
                f"[闪变] 国家标准 solarStandard={_flicker_std}，周期补齐={_flicker_cycle}s"
            )
        except Exception:
            pass
    strShowErrorMessageBoxFlag = "0"
    if strAddTestFlag == "0":
        strArrayTest = []
    else:
        strArraySingle = ["" for _ in range(10)]
        S1Command = "*IDN?"
        strArraySingle[0] = "AC"
        strArraySingle[1] = "query"
        strArraySingle[2] = S1Command
        strArraySingle[9] = 1500
        strArrayTest.append(strArraySingle)

    strArrayTestStep = []
    # 收集所有 DC 错误信息
    dc_error_messages = []

    S1ACEACHStatus = uiThaiDianYaShanBian.comboBox_S1_AC_2.currentText()
    # 预先读取跨 step 复用参数，避免某个 step 未勾选时出现未定义变量
    S1ACVOLT = uiThaiDianYaShanBian.textEdit_S1_AC_VOLT.toPlainText()
    S1ACFR = uiThaiDianYaShanBian.textEdit_S1_AC_FR.toPlainText()

    # ── 每组闪变次数：德威创模式读 DEWETRON 字段，WT 模式读 WT 字段 ──
    if is_dewetron:
        S2_PER_FLICK_COUNT = uiThaiDianYaShanBian.comboBox_DEW_S2_PER_FLICK_COUNT.currentText()
    else:
        S2_PER_FLICK_COUNT = uiThaiDianYaShanBian.comboBox_S2_PER_FLICK_COUNT.currentText()

