# 谐波电流 
def thaixiebodianliuSend():
    global uiThaiXieBoDianLiu, strArrayTest, dialog_windowxiebodianliu
    global strSettingTestFlag, strArrayTestStep
    global strAddTestFlag, total_save_file, WT_is_checked, test_program
    # 多项目切换测试相关参数
    global project_change, wt_config_nums, integral_status
    global uiThiaWT3000E, uiThiaWT1800, uiThiaWT1806E, uiThiaWT5000
    global command_save_file_path, wt_type
    global harmonic_append_count
    if 'harmonic_append_count' not in globals():
        harmonic_append_count = 0

    # ── 德威创模式标记 ──
    is_dewetron = hasattr(uiThaiXieBoDianLiu, '_mode') and uiThaiXieBoDianLiu._mode == 'dewetron'

    strShowErrorMessageBoxFlag = "0"
    # 收集所有 DC 错误信息
    dc_error_messages = []
    # 初始化 DC 变量，防止未勾选 step1 DC 通道时在谐波步骤中引用报错
    S1DC1Vmp = S1DC1Imp = S1DC1Voc = S1DC1Isc = ""
    S1DC2Vmp = S1DC2Imp = S1DC2Voc = S1DC2Isc = ""
    S1DC3Vmp = S1DC3Imp = S1DC3Voc = S1DC3Isc = ""
    S1DC4Vmp = S1DC4Imp = S1DC4Voc = S1DC4Isc = ""
    if strAddTestFlag == "0":
        strArrayTest = []
        total_save_file = 0
        test_program = []

    if strAddTestFlag == "0" or (strAddTestFlag == "1" and not is_dewetron):  # 同项目追加也刷新录波文件名
        if not is_dewetron:
            if uiThaiXieBoDianLiu.radioButton_S2_WT3000.isChecked():
                page = uiThaiXieBoDianLiu._wtStacked.widget(0)
                wt_config_dict = WT3000E_params_config(_PageWidgetFinder(page))
            elif uiThaiXieBoDianLiu.radioButton_S2_WT1800.isChecked():
                page = uiThaiXieBoDianLiu._wtStacked.widget(1)
                wt_config_dict = WT1800_params_config(_PageWidgetFinder(page))
            elif uiThaiXieBoDianLiu.radioButton_S2_WT1806E.isChecked():
                page = uiThaiXieBoDianLiu._wtStacked.widget(2)
                wt_config_dict = WT1806E_params_config(_PageWidgetFinder(page))
            elif uiThaiXieBoDianLiu.radioButton_S2_WT5000.isChecked():
                page = uiThaiXieBoDianLiu._wtStacked.widget(3)
                wt_config_dict = WT5000_params_config(_PageWidgetFinder(page))

            from utils.wt_recording_mode import (
                apply_filename_list_to_wt_pages,
                combo_index_to_mode,
                collect_harmonic_power_percents,
                harmonic_recommended_filenames,
                previous_wt_filename_list,
            )
            _rec_mode = combo_index_to_mode(
                uiThaiXieBoDianLiu.comboBox_S3_record_mode.currentIndex()
            )
            # 每轮追加带时分秒后缀；结束试验清零计数后再追加也不会盖文件
            _run_tag = time.strftime("%H%M%S")
            file_names = harmonic_recommended_filenames(
                collect_harmonic_power_percents(uiThaiXieBoDianLiu),
                _rec_mode,
                run_tag=_run_tag,
            )
            if strAddTestFlag == "1":
                prev_names = previous_wt_filename_list(strArrayTest)
                if prev_names:
                    file_names = list(prev_names) + list(file_names)
            apply_filename_list_to_wt_pages(uiThaiXieBoDianLiu._wtStacked, file_names)
            if file_names:
                file_list_text = ",".join(file_names)
                wt_config_dict["textEdit_FileNameList"] = file_list_text
                if wt_config_dict.get("comboBox_AutoSave", 0) == 0:
                    wt_config_dict["comboBox_AutoSave"] = 1
                try:
                    for page_idx in range(uiThaiXieBoDianLiu._wtStacked.count()):
                        page = uiThaiXieBoDianLiu._wtStacked.widget(page_idx)
                        te = page.findChild(QtWidgets.QTextEdit, "textEdit_FileNameList")
                        if te is not None:
                            te.setPlainText(file_list_text)
                except Exception as e:
                    _append_debug_log(f"[谐波] update WT FileNameList failed: {e}")

            strArraySingle = ["" for _ in range(10)]
            S1Command = wt_config_dict
            strArraySingle[0] = "Upper_WT_Config"
            strArraySingle[3] = "config_dict"
            strArraySingle[4] = S1Command
            strArrayTest.append(strArraySingle)

    # ── DEWETRON 模式 Step2：NUMERIC 配置 + 启动采集 ──
    # CSV 导出通过 collector 的 NUMERIC query 实现，不需要 :STORE: 命令
    # 谐波 step2 是共用 checkBox_S2（包住 WT/DEW 栈）；未勾时后面仍兜底补 START
    if is_dewetron and uiThaiXieBoDianLiu.checkBox_S2.isChecked():
        s = ["" for _ in range(10)]
        s[0], s[1], s[2] = "DEWETRON", "write", ":ACQUISITION:START"
        strArrayTest.append(s)

        ui.textEdit_ReturnMessage.append(
            f"[谐波] 德威创模式：启动采集（NUMERIC 配置由 collector 执行）")

    if strAddTestFlag == '1' and project_change == '1' and not is_dewetron:
        strArraySingle = ["" for _ in range(10)]
        S1Command = ""
        strArraySingle[0] = "AC"
        strArraySingle[1] = "wait"
        strArraySingle[2] = S1Command
        strArraySingle[9] = 3000
        strArrayTest.append(strArraySingle)
        wt_config_nums = _bump_wt_config_nums()
        
    strArrayTestStep = []
    # 交流源相数
    strArraySingle = ["" for _ in range(10)]

    # step1
    if uiThaiXieBoDianLiu.checkBox_S1.isChecked():
        strArrayTestStepSingle = []
        S1_TIME_VALUE = uiThaiXieBoDianLiu.textEdit_S1_TIME.toPlainText()
        S1_TIME_UNIT = uiThaiXieBoDianLiu.comboBox_S1_TIME.currentText()
        fS1SetTime = float(S1_TIME_VALUE)
        fS1SetTime = SetTimeFunction(fS1SetTime, S1_TIME_UNIT)

        # AC
        S1ACStatus = uiThaiXieBoDianLiu.comboBox_S1_AC.currentText()
        S1_ACWaitTimeValue = uiThaiXieBoDianLiu.textEdit_S1_ACWaitTIME.toPlainText()
        S1_ACWaitTimeUnit = uiThaiXieBoDianLiu.comboBox_S1_ACWaitTIME.currentText()
        fS1ACWaitTime = float(S1_ACWaitTimeValue)
        fS1ACWaitTime = SetTimeFunction(fS1ACWaitTime, S1_ACWaitTimeUnit)

        # 1or3
        # 共用 AC 启机（爱科同压: EDIT ALL + 一次 VOLT/FREQ）
        append_ac_startup_from_ui(uiThaiXieBoDianLiu, strArrayTest, strArrayTestStepSingle)
        strArraySingle = ["" for _ in range(10)]
        if S1ACStatus == "开启":
            strArraySingle[0] = "AC"
            strArraySingle[1] = "write"
            strArraySingle[2] = "OUTP ON"
        elif S1ACStatus == "关闭":
            strArraySingle[0] = "AC"
            strArraySingle[1] = "write"
            strArraySingle[2] = "OUTP OFF"
        strArrayTest.append(strArraySingle)
        strArrayTestStepSingle.append(strArraySingle)

        strArraySingle = ["" for _ in range(10)]
        S1Command = "*IDN?"
        strArraySingle[0] = "AC"
        strArraySingle[1] = "query"
        strArraySingle[2] = S1Command
        strArraySingle[8] = 5
        strArrayTest.append(strArraySingle)
        strArrayTestStepSingle.append(strArraySingle)

        # DC1
        if uiThaiXieBoDianLiu.checkBox_S1_DC1.isChecked():
            S1DC1Vmp = uiThaiXieBoDianLiu.textEdit_S1_DC1_VOLT.toPlainText()
            S1DC1Imp = uiThaiXieBoDianLiu.textEdit_S1_DC1_CURR.toPlainText()
            S1DC1Voc = uiThaiXieBoDianLiu.textEdit_S1_DC1_Voc.toPlainText()
