    def get_time(time_edit_name, combo_box_name, ui=uiThaiFixedPF):
        """
        通过控件名获取转换后的时间值
        参数:
            time_edit_name: 时间输入框的控件名（字符串）
            combo_box_name: 单位下拉框的控件名（字符串）
            ui: ui对象，默认为uiThaiFixedPF
        返回:
            float: 转换后的时间值
        """
        time_edit = getattr(ui, time_edit_name)
        combo_box = getattr(ui, combo_box_name)
        
        time_value = time_edit.toPlainText() if hasattr(time_edit, 'toPlainText') else time_edit.text()
        time_unit = combo_box.currentText()
        f_set_time = float(time_value)
        return SetTimeFunction(f_set_time, time_unit)

    # 使用示例
    # fS1SetTime = get_processed_time_by_name('textEdit_S1_TIME', 'comboBox_S1_TIME')
    
    def get_time_dynamic(prefix, suffix, ui=uiThaiFixedPF):
        """
        动态生成控件名并获取处理后的时间
        
        参数:
            prefix: 前缀字符串，如 "S3", "S4" 等
            suffix: 后缀编号，如 "1", "2" 等
            ui: UI对象，默认为 uiThaiFixedPF
            
        返回:
            float: 转换后的时间值
            
        使用示例:
            # 获取 lE_S3_1 和 cB_S3_unit_1 的时间值
            time_S3_1 = get_processed_time_dynamic("S3", "1")
            
            # 获取 lE_S4_1 和 cB_S4_unit_1 的时间值
            time_S4_1 = get_processed_time_dynamic("S4", "1")
            
            # 获取 lE_S4_2 和 cB_S4_unit_2 的时间值
            time_S4_2 = get_processed_time_dynamic("S4", "2")
        """
        # 动态生成控件名称
        time_edit_name = f"lE_{prefix}_{suffix}"
        combo_box_name = f"cB_{prefix}_unit_{suffix}"
        
        # 调用之前封装的函数
        return get_time(time_edit_name, combo_box_name, ui)



