def thaioverloadsSend():
    global uiThaiOverLoads, strArrayTest, dialog_windowoverloads
    global strSettingTestFlag, strArrayTestStep
    global strAddTestFlag, total_save_file, WT_is_checked, test_program
    # 多项目切换测试相关参数
    global project_change, wt_config_nums
    global uiThiaWT3000E, uiThiaWT1800, uiThiaWT1806E, uiThiaWT5000
    global command_save_file_path, wt_type, overloads_append_count
    if 'overloads_append_count' not in globals():
        overloads_append_count = 0

    strShowErrorMessageBoxFlag = "0"
    if strAddTestFlag == "0":
        strArrayTest = []
        total_save_file = 0
        test_program = []

    if strAddTestFlag == "0" or strAddTestFlag == "1":  # 同项目追加也刷新录波文件名
        if uiThaiOverLoads.radioButton_S2_WT3000.isChecked():
            wt_config_dict = WT3000E_params_config(_PageWidgetFinder(uiThaiOverLoads._wtStacked.widget(0)))
        elif uiThaiOverLoads.radioButton_S2_WT1800.isChecked():
            wt_config_dict = WT1800_params_config(_PageWidgetFinder(uiThaiOverLoads._wtStacked.widget(1)))
        elif uiThaiOverLoads.radioButton_S2_WT1806E.isChecked():
            wt_config_dict = WT1806E_params_config(_PageWidgetFinder(uiThaiOverLoads._wtStacked.widget(2)))
        elif uiThaiOverLoads.radioButton_S2_WT5000.isChecked():
            wt_config_dict = WT5000_params_config(_PageWidgetFinder(uiThaiOverLoads._wtStacked.widget(3)))

        from utils.wt_recording_mode import (
            apply_filename_list_to_wt_pages,
            overload_recommended_filenames,
        )
        from utils.matrix_recording_commands import get_record_mode

        _rec_mode = get_record_mode(uiThaiOverLoads)
        file_names = overload_recommended_filenames(_rec_mode)
        apply_filename_list_to_wt_pages(uiThaiOverLoads._wtStacked, file_names)
        if file_names:
            file_names = _finalize_recording_file_names(file_names)
            file_list_text = ",".join(file_names)
            wt_config_dict["textEdit_FileNameList"] = file_list_text
            if wt_config_dict.get("comboBox_AutoSave", 0) == 0:
                wt_config_dict["comboBox_AutoSave"] = 1
            try:
                for page_idx in range(uiThaiOverLoads._wtStacked.count()):
                    page = uiThaiOverLoads._wtStacked.widget(page_idx)
                    te = page.findChild(QtWidgets.QTextEdit, "textEdit_FileNameList")
                    if te is not None:
                        te.setPlainText(file_list_text)
                    combo = page.findChild(QtWidgets.QComboBox, "comboBox_AutoSave")
                    if combo is not None and combo.currentIndex() == 0:
                        combo.setCurrentIndex(1)
            except Exception as e:
                _append_debug_log(f"[overloads] update WT FileNameList failed: {e}")

        strArraySingle = ["" for _ in range(10)]
        S1Command = wt_config_dict
        strArraySingle[0] = "Upper_WT_Config"
        strArraySingle[3] = "config_dict"
        strArraySingle[4] = S1Command
        strArrayTest.append(strArraySingle)

    if strAddTestFlag == '1' and project_change == '1':
        strArraySingle = ["" for _ in range(10)]
        S1Command = ""
        strArraySingle[0] = "AC"
        strArraySingle[1] = "wait"
        strArraySingle[2] = S1Command
        strArraySingle[9] = 3000
        strArrayTest.append(strArraySingle)
        wt_config_nums = _bump_wt_config_nums()
        
    strArrayTestStep = []
    # 交流源相数
    strArraySingle = ["" for _ in range(10)]

    # step1
    if uiThaiOverLoads.checkBox_S1.isChecked():
        strArrayTestStepSingle = []
        S1_TIME_VALUE = uiThaiOverLoads.textEdit_S1_TIME.toPlainText()
        S1_TIME_UNIT = uiThaiOverLoads.comboBox_S1_TIME.currentText()
        fS1SetTime = float(S1_TIME_VALUE)
        fS1SetTime = SetTimeFunction(fS1SetTime, S1_TIME_UNIT)

