        S3ACSTART = float(S3ACSTART)
        S3ACSTOP = float(S3ACSTOP)
        S3ACRANGEPOINT = int(S3ACRANGEPOINT)
        S3ACRANGESTEP = float(S3ACRANGESTEP)

