def thaicosPhiBrazilSend():
    global uiThaiCosPhiBrazil,dialog_windowcosPhiBrazil,strArrayTest,Ui_Dialog_thaicosPhiBrazil
    global strSettingTestFlag,strArrayTestStep
    global strAddTestFlag, total_save_file, WT_is_checked, test_program
    # 多项目切换测试相关参数
    global project_change, wt_config_nums
    global uiThiaWT3000E, uiThiaWT1800, uiThiaWT1806E, uiThiaWT5000
    global command_save_file_path, wt_type
    global cosPhiBrazil_append_count
    if 'cosPhiBrazil_append_count' not in globals():
        cosPhiBrazil_append_count = 0

    strShowErrorMessageBoxFlag = ''
    if strAddTestFlag == "0":
        strArrayTest = []
        total_save_file = 0
        test_program = []
        wt_config_nums = 0
    
    if strAddTestFlag == "0" or strAddTestFlag == "1":  # 同项目追加也刷新录波文件名
        if uiThaiCosPhiBrazil.radioButton_S2_WT3000.isChecked():
            wt_config_dict = WT3000E_params_config(_PageWidgetFinder(uiThaiCosPhiBrazil._wtStacked.widget(0)))
        elif uiThaiCosPhiBrazil.radioButton_S2_WT1800.isChecked():
            wt_config_dict = WT1800_params_config(_PageWidgetFinder(uiThaiCosPhiBrazil._wtStacked.widget(1)))
        elif uiThaiCosPhiBrazil.radioButton_S2_WT1806E.isChecked():
            wt_config_dict = WT1806E_params_config(_PageWidgetFinder(uiThaiCosPhiBrazil._wtStacked.widget(2)))
        elif uiThaiCosPhiBrazil.radioButton_S2_WT5000.isChecked():
            wt_config_dict = WT5000_params_config(_PageWidgetFinder(uiThaiCosPhiBrazil._wtStacked.widget(3)))

        strArraySingle = ["" for _ in range(10)]
        S1Command = wt_config_dict
        strArraySingle[0] = "Upper_WT_Config"
        strArraySingle[3] = "config_dict"
        strArraySingle[4] = S1Command
        strArrayTest.append(strArraySingle)

        # 巴西 CosPhi：此处走"上位机自动配置 WTViewerEfree"的逻辑（Upper_WT_Config + auto_config），不依赖 RecPlayer 宏文件
        _append_debug_log("[cosPhiBrazil] WT config via Upper_WT_Config (no macro replay file in this project)")
    
    if strAddTestFlag == '1' and project_change == '1':
        strArraySingle = ["" for _ in range(10)]
        S1Command = ""
        strArraySingle[0] = "AC"
        strArraySingle[1] = "wait"
        strArraySingle[2] = S1Command
        strArraySingle[9] = 3000
        strArrayTest.append(strArraySingle)
        wt_config_nums = _bump_wt_config_nums()

    strArrayTestStep = []
    strArraySingle = ["" for _ in range(10)]
    # step1
    if uiThaiCosPhiBrazil.checkBox_S1.isChecked():
        strArrayTestStepSingle = []
        S1_TIME_VALUE = uiThaiCosPhiBrazil.textEdit_S1_TIME.toPlainText()
        S1_TIME_UNIT = uiThaiCosPhiBrazil.comboBox_S1_TIME.currentText()
        fS1SetTime = float(S1_TIME_VALUE)
        fS1SetTime = SetTimeFunction(fS1SetTime, S1_TIME_UNIT)

        # AC
        S1_ACWaitTimeValue = uiThaiCosPhiBrazil.textEdit_S1_ACWaitTIME.toPlainText()
        S1_ACWaitTimeUnit = uiThaiCosPhiBrazil.comboBox_S1_ACWaitTIME.currentText()
        fS1ACWaitTime = float(S1_ACWaitTimeValue)
        fS1ACWaitTime = SetTimeFunction(fS1ACWaitTime, S1_ACWaitTimeUnit)
        S1ACStatus = uiThaiCosPhiBrazil.comboBox_S1_AC.currentText()

        # 共用 AC 启机（爱科同压: EDIT ALL + 一次 VOLT/FREQ）
        append_ac_startup_from_ui(uiThaiCosPhiBrazil, strArrayTest, strArrayTestStepSingle)
        strArraySingle = ["" for _ in range(10)]
        if S1ACStatus == "开启":
            strArraySingle[0] = "AC"
            strArraySingle[1] = "write"
            strArraySingle[2] = "OUTP ON"
            strArraySingle[9] = fS1ACWaitTime
        elif S1ACStatus == "关闭":
            strArraySingle[0] = "AC"
            strArraySingle[1] = "write"
            strArraySingle[2] = "OUTP OFF"
            strArraySingle[9] = fS1ACWaitTime
        strArrayTest.append(strArraySingle)
        strArrayTestStepSingle.append(strArraySingle)

        # DC1
        if uiThaiCosPhiBrazil.checkBox_S1_DC1.isChecked():
            S1DC1Vmp = uiThaiCosPhiBrazil.textEdit_S1_DC1_VOLT.toPlainText()
            S1DC1Imp = uiThaiCosPhiBrazil.textEdit_S1_DC1_CURR.toPlainText()
            S1DC1Voc = uiThaiCosPhiBrazil.textEdit_S1_DC1_Voc.toPlainText()
            S1DC1Isc = uiThaiCosPhiBrazil.textEdit_S1_DC1_Isc.toPlainText()
            S1DC1PF = uiThaiCosPhiBrazil.textEdit_S1_DC1_PF.toPlainText()
            a = DCGetIVValueFunction(S1DC1Vmp,S1DC1Imp,S1DC1Voc,S1DC1Isc,S1DC1PF, 0)
            if a == "1":
                strShowErrorMessageBoxFlag = "1"
            elif a == "2":
                strShowErrorMessageBoxFlag = "2"
            elif a == "3":
                strShowErrorMessageBoxFlag = "brand"
            else:
                strArrayTestStepSingle = DC_IV_Commands_Set(strArrayTestStepSingle, a, "DC1")

            strArraySingle = ["" for _ in range(10)]
            S1DC1Status = uiThaiCosPhiBrazil.comboBox_S1_DC1.currentText()
            if S1DC1Status == "开启":
                strArraySingle[0] = "DC1"
                strArraySingle[1] = "write"
                strArraySingle[2] = "OUTP ON"
            elif S1DC1Status == "关闭":
                strArraySingle[0] = "DC1"
                strArraySingle[1] = "write"
                strArraySingle[2] = "OUTP OFF"
            strArrayTest.append(strArraySingle)
            strArrayTestStepSingle.append(strArraySingle)

            strArraySingle = ["" for _ in range(10)]
            S1Command = "*IDN?"
            strArraySingle[0] = "AC"
            strArraySingle[1] = "query"
            strArraySingle[2] = S1Command
            strArraySingle[8] = 5
            strArrayTest.append(strArraySingle)
            strArrayTestStepSingle.append(strArraySingle)
        
        # DC2
