    strArrayTestStep = []
    strArraySingle = ["" for _ in range(10)]
    S1ACEACHStatus = uiThaiVoltProtect10min.comboBox_S1_AC_2.currentText()
    # 连续录：从①额定保持（抬压前）就开始，覆盖 Un 段 + 过压 + 恢复
    use_ov_continuous = False
    fS1SetTime = 0
    # step1
    if uiThaiVoltProtect10min.checkBox_S1.isChecked():
        strArrayTestStepSingle = []
        S1_TIME_VALUE = uiThaiVoltProtect10min.textEdit_S1_TIME.toPlainText()
        S1_TIME_UNIT = uiThaiVoltProtect10min.comboBox_S1_TIME.currentText()
        fS1SetTime = float(S1_TIME_VALUE)
        fS1SetTime = SetTimeFunction(fS1SetTime, S1_TIME_UNIT)

        # AC
        S1_ACWaitTimeValue = uiThaiVoltProtect10min.textEdit_S1_ACWaitTIME.toPlainText()
        S1_ACWaitTimeUnit = uiThaiVoltProtect10min.comboBox_S1_ACWaitTIME.currentText()
        fS1ACWaitTime = float(S1_ACWaitTimeValue)
        fS1ACWaitTime = SetTimeFunction(fS1ACWaitTime, S1_ACWaitTimeUnit)
        S1ACStatus = uiThaiVoltProtect10min.comboBox_S1_AC.currentText()

        # 共用 AC 启机（爱科同压: EDIT ALL + 一次 VOLT/FREQ）
        append_ac_startup_from_ui(uiThaiVoltProtect10min, strArrayTest, strArrayTestStepSingle)
        strArraySingle = ["" for _ in range(10)]
        from utils.iot_boot_params_sync import is_output_on as _iot_out_on

        if _iot_out_on(S1ACStatus, default=True):
            strArraySingle[0] = "AC"
            strArraySingle[1] = "write"
            strArraySingle[2] = "OUTP ON"
            strArraySingle[9] = fS1ACWaitTime
        else:
            strArraySingle[0] = "AC"
            strArraySingle[1] = "write"
            strArraySingle[2] = "OUTP OFF"
            strArraySingle[9] = fS1ACWaitTime
        strArrayTest.append(strArraySingle)
        strArrayTestStepSingle.append(strArraySingle)

        # DC1
        if uiThaiVoltProtect10min.checkBox_S1_DC1.isChecked():
            S1DC1Vmp = uiThaiVoltProtect10min.textEdit_S1_DC1_VOLT.toPlainText()
            S1DC1Imp = uiThaiVoltProtect10min.textEdit_S1_DC1_CURR.toPlainText()
