def _get_dewetron_section(project_name=None):
    """Return the registered analyzer-mode section for a project."""
    name = project_name or ui.comboBox_PS.currentText()
    try:
        return dewetron_coordinator.section(name)
    except Exception:
        return None


def _is_dewetron_project_mode(project_name=None):
    """Return whether the selected project's shared analyzer section uses DEWETRON."""
    name = project_name or ui.comboBox_PS.currentText()
    section = _get_dewetron_section(name)
    if section is not None:
        try:
            return dewetron_coordinator.current_mode(name) == MODE_DEWETRON
        except (KeyError, ValueError):
            pass
    if name == '电压闪变':
        try:
            from setup.main_setup import LazyDialog
            if isinstance(uiThaiDianYaShanBian, LazyDialog) and not uiThaiDianYaShanBian.is_created:
                return False
        except Exception:
            pass
        return getattr(uiThaiDianYaShanBian, '_mode', None) == 'dewetron'
    if name == '谐波电流':
        try:
            from setup.main_setup import LazyDialog
            if isinstance(uiThaiXieBoDianLiu, LazyDialog) and not uiThaiXieBoDianLiu.is_created:
                return False
        except Exception:
            pass
        return getattr(uiThaiXieBoDianLiu, '_mode', None) == 'dewetron'
    return False


def _save_current_dewetron_commands():
    """Persist the current command plan into the active collector run once."""
    if dewetron_collector is None or not dewetron_collector.current_batch():
        return False
    if not dewetron_collector.current_run():
        if not dewetron_collector.begin_run():
            return False
    dewetron_collector.save_commands(strArrayTest)
    return True


def _prepare_dewetron_collector(project_name):
    """预处理 DEWETRON 采集器：校验字段、映射 RATE、确定保存路径。

    在 command.csv 开始执行前调用，避免采集启动时的延迟。
    """
    print(f"[_prepare_dewetron_collector] === 开始预处理 === project={project_name}")
    global dewetron_collector
    if dewetron_collector is None:
        print("[_prepare_dewetron_collector] dewetron_collector 为 None，跳过")
        return

    # 1. 根据项目类型获取用户选择的字段
    fields = []
    rate_text = 'Default'
    save_path = ''
    test_type = ''  # SQLite 测试类型
    decimal_places = 4
    export_abs_time = False
    keep_oxygen_dmd = False

    def _dew_checkbox_checked(owner, name):
        box = getattr(owner, name, None) if owner is not None else None
        return bool(box.isChecked()) if box is not None else False

    if project_name == '电压闪变':
        print("[_prepare_dewetron_collector] 项目: 电压闪变")
        test_type = 'flicker'
        # 从闪变对话框获取字段选择
        if hasattr(uiThaiDianYaShanBian, 'get_checked_export_fields'):
            fields = uiThaiDianYaShanBian.get_checked_export_fields()
            print(f"[{_prepare_dewetron_collector.__name__}] get_checked_export_fields 返回: {fields}")
        else:
            print(f"[{_prepare_dewetron_collector.__name__}] uiThaiDianYaShanBian 没有 get_checked_export_fields 方法")
        rate_text = uiThaiDianYaShanBian.comboBox_DEW_MaxRefreshRate.currentText()
        spin = getattr(uiThaiDianYaShanBian, 'spinBox_DEW_DecimalPlaces', None)
        if spin is not None:
            decimal_places = spin.value()
        export_abs_time = _dew_checkbox_checked(
            uiThaiDianYaShanBian, 'checkBox_DEW_ExportAbsTime'
        )
        keep_oxygen_dmd = _dew_checkbox_checked(
            uiThaiDianYaShanBian, 'checkBox_DEW_KeepOxygenDmd'
        )
        # 数据直接入 db，导出时再选择路径，这里生成默认路径供参考
        from utils.dewetron_recording import resolve_dewetron_save_paths

        save_path = resolve_dewetron_save_paths(
            test_type="flicker", continuous=True
        )[0]
        print(f"[{_prepare_dewetron_collector.__name__}] rate_text={rate_text}")

    elif project_name == '谐波电流':
        print("[_prepare_dewetron_collector] 项目: 谐波电流")
        test_type = 'harmonic'
        # 从谐波电流对话框获取字段选择
        if hasattr(uiThaiXieBoDianLiu, 'get_checked_export_fields'):
            fields = uiThaiXieBoDianLiu.get_checked_export_fields()
        if hasattr(uiThaiXieBoDianLiu, 'comboBox_DEW_MaxRefreshRate'):
            rate_text = uiThaiXieBoDianLiu.comboBox_DEW_MaxRefreshRate.currentText()
        spin = getattr(uiThaiXieBoDianLiu, 'spinBox_DEW_DecimalPlaces', None)
        if spin is not None:
            decimal_places = spin.value()
        export_abs_time = _dew_checkbox_checked(
            uiThaiXieBoDianLiu, 'checkBox_DEW_ExportAbsTime'
        )
        keep_oxygen_dmd = _dew_checkbox_checked(
            uiThaiXieBoDianLiu, 'checkBox_DEW_KeepOxygenDmd'
        )
        # 数据直接入 db，导出时再选择路径
        from utils.dewetron_recording import resolve_dewetron_save_paths

        save_path = resolve_dewetron_save_paths(
            test_type="harmonic", continuous=True
        )[0]

    else:
        section = _get_dewetron_section(project_name)
        spec = get_project_spec(project_name)
        if section is None or spec is None:
            message = f"项目 {project_name} 未注册 DEWETRON 配置"
            ui.textEdit_ReturnMessage.append(f"[DEWETRON] {message}")
            return False
        config = section.get_dewetron_config()
        errors = config.validation_errors(require_export_fields=True)
        current_fingerprint = config_fingerprint(
            config, test_type=spec.test_type, profile=spec.profile
        )
        if (
            getattr(section, '_dew_config_dirty', True)
            or getattr(section, '_dew_applied_fingerprint', None) != current_fingerprint
        ):
            if not _ensure_dewetron_config_applied(project_name, silent=True):
                errors.append("DEWETRON配置尚未应用，请先点击测试生效")
            else:
                current_fingerprint = config_fingerprint(
                    config, test_type=spec.test_type, profile=spec.profile
                )
                if (
                    getattr(section, '_dew_config_dirty', True)
                    or getattr(section, '_dew_applied_fingerprint', None)
                    != current_fingerprint
                ):
                    errors.append("DEWETRON配置尚未应用，请先点击测试生效")
        if errors:
            for error in errors:
                ui.textEdit_ReturnMessage.append(f"[DEWETRON] {error}")
            return False
        fields = config.export_fields
        rate_text = config.rate_text
        decimal_places = getattr(config, 'decimal_places', 4)
        export_abs_time = bool(getattr(config, 'export_abs_time', False))
        keep_oxygen_dmd = bool(getattr(config, 'keep_oxygen_dmd', False))
        test_type = spec.test_type
        paths = list(getattr(section, "_dew_save_paths", None) or [])
        if paths:
            save_path = paths[0]
            section._dew_save_index = 0
        else:
            from utils.dewetron_recording import resolve_dewetron_save_paths

            dew_base = str(getattr(config, "save_dir", "") or "").strip() or None
            paths = resolve_dewetron_save_paths(
                test_type=str(test_type or "dewetron"),
                continuous=True,
                base_dir=dew_base,
            )
            save_path = paths[0]
            section._dew_save_paths = list(paths)
            section._dew_save_index = 0

    print(f"[_prepare_dewetron_collector] fields={fields}")

    if not fields:
        print("[_prepare_dewetron_collector] 未选择任何采集字段")
        ui.textEdit_ReturnMessage.append("[DEWETRON] 未选择任何采集字段，试验未启动")
        return False

    # 2. 调用采集器的 prepare 方法（校验字段、映射 RATE、初始化 SQLite）
    print(f"[_prepare_dewetron_collector] 调用 prepare: fields={len(fields)} 个, rate={rate_text}, "
          f"test_type={test_type}, path={save_path}, decimal_places={decimal_places}, "
          f"abs_time={export_abs_time}, keep_dmd={keep_oxygen_dmd}")
    def _prepare_work():
        return dewetron_collector.prepare(
            fields,
            rate_text,
            test_type,
            save_path,
            decimal_places=decimal_places,
            export_abs_time=export_abs_time,
            keep_oxygen_dmd=keep_oxygen_dmd,
        )

    try:
        result = _run_device_io("DewetronPrepare", _prepare_work)
    except Exception as exc:
        ui.textEdit_ReturnMessage.append(f"[DEWETRON] 采集准备异常: {exc}")
        return False
    if result is None:
        ui.textEdit_ReturnMessage.append("[DEWETRON] 采集准备进行中，请稍候再开始")
        return False
    valid_fields, warnings = result

    # 3. 显示校验结果；失败时不创建批次，也不放行执行线程
    for warning in warnings:
        ui.textEdit_ReturnMessage.append(f"[DEWETRON] {warning}")
    if not getattr(result, 'success', bool(valid_fields)):
        error = getattr(result, 'error', None) or '采集准备失败'
        ui.textEdit_ReturnMessage.append(f"[DEWETRON] {error}")
        return False

    batch_id = dewetron_collector.begin_batch(test_type, save_path)
    if not batch_id:
        ui.textEdit_ReturnMessage.append("[DEWETRON] 无法创建采集批次")
        return False
    if not _save_current_dewetron_commands():
        dewetron_collector.finish_batch()
        ui.textEdit_ReturnMessage.append("[DEWETRON] 无法保存当前命令计划")
        return False

    ui.textEdit_ReturnMessage.append(
        f"[DEWETRON] 采集准备完成: {len(valid_fields)} 个有效字段, "
        f"间隔 {parse_rate_ms(rate_text)}ms, 批次: {dewetron_collector.get_batch_uid()}"
    )
    return True


def RunProjectPush():
    global strTestFlag,strSettingTestFlag, WT_is_checked, test_program, heading_handle, flicker_is_test
    global strArrayTest, flicker_append_count

    currentSecond = ui.comboBox_PS.currentText()
    is_dewetron = _is_dewetron_project_mode(currentSecond)
    if 'flicker_append_count' not in globals():
        flicker_append_count = 0
    if currentSecond == '电压闪变' and flicker_append_count == 0 and strSettingTestFlag != "1":
        QMessageBox.warning(None, "提示", "请先追加测试配置后再开始试验")
        return

    if strSettingTestFlag != "1" or not strArrayTest:
        msg = (
            "还没有可执行的试验命令。请先打开项目点「测试追加」，"
            "并确认操作日志出现「追加完成」。"
            "若追加时弹过错误，开始按钮即使亮了也不会真正启动。"
        )
        ui.textEdit_ReturnMessage.append("[开始试验] " + msg)
        logger.info("请设定实验内容: strSettingTestFlag=%r commands=%s" % (
            strSettingTestFlag, len(strArrayTest) if strArrayTest else 0
        ))
        box = QMessageBox(None)
        box.setIcon(QMessageBox.Warning)
        box.setWindowTitle("提示")
        box.setText(msg)
        box.setWindowFlags(box.windowFlags() | Qt.WindowStaysOnTopHint)
        box.exec_()
        return

    try:
        heading_handle = get_enumwindows()
        print("父句柄更新！")
        logger.info(f"父句柄更新：{heading_handle}")
    except Exception as exc:
        heading_handle = {}
        logger.info("枚举窗口失败（可继续）：%s" % exc)

    if strSettingTestFlag == "1":
        # 设备连接校验：根据 strArrayTest 中实际用到的设备，一次性检查所有连接
        disconnected = _check_device_connections()
        if disconnected:
            msg = f"以下设备未连接，已终止本次试验启动：{disconnected}"
            ui.textEdit_ReturnMessage.append(f"[开始试验] {msg}")
            logger.info(f"设备未连接，终止启动：{disconnected}")
            print(f"设备未连接，终止启动：{disconnected}")
            box = QMessageBox(None)
            box.setIcon(QMessageBox.Warning)
            box.setWindowTitle("连接错误")
            box.setText(f"以下设备未连接，已终止本次试验启动：\n\n{disconnected}")
            box.setWindowFlags(box.windowFlags() | Qt.WindowStaysOnTopHint)
            box.exec_()
            return

        # 已在跑：中途追加的命令会由 RunProject while 接着执行，不要再点开始新开 IOT 单
        _run_flag = str(globals().get("strTestStatusFlag") or "").strip()
        if _run_flag in ("运行", "暂停"):
            msg = (
                f"试验已在「{_run_flag}」中。中途追加的项目会按同一命令队列继续执行，"
                "无需再次「开始试验」；再次开始会误把当前 IOT 任务结案并新开一单。"
            )
            ui.textEdit_ReturnMessage.append("[开始试验] " + msg)
            logger.info(msg)
            box = QMessageBox(None)
            box.setIcon(QMessageBox.Information)
            box.setWindowTitle("试验进行中")
            box.setText(msg)
            box.setWindowFlags(box.windowFlags() | Qt.WindowStaysOnTopHint)
            box.exec_()
            return

        # 云端 handoff 占用本台架时拦截本机开测（双开测并存互斥）。
        # 注意：云任务自己调用 start_test 时 _job_ctx 仍在，必须放行，否则会自锁。
        try:
            from utils.iot_local_run import (
                handoff_has_awaiting_job,
                handoff_start_in_progress,
            )

            if handoff_has_awaiting_job() and not handoff_start_in_progress():
                msg = "云端任务占用本台架，请先结束/中止云端任务后再本机开测"
                ui.textEdit_ReturnMessage.append("[开始试验] " + msg)
                logger.info(msg)
                box = QMessageBox(None)
                box.setIcon(QMessageBox.Warning)
                box.setWindowTitle("台架占用")
                box.setText(msg)
                box.setWindowFlags(box.windowFlags() | Qt.WindowStaysOnTopHint)
                box.exec_()
                return
        except Exception as _iot_mutex_exc:
            print(f"[RunProject] IOT 互斥检查跳过: {_iot_mutex_exc}", flush=True)

        # 输出上限门禁（与 IOT handoff 共用；期望全 null 则跳过）
        try:
            from utils.iot_output_limits import (
                evaluate_controllers_output_limits_gate,
                map_per_dc_factor_to_brands,
            )

            # 仅校验命令队列实际用到的直流槽，避免未勾选的 DC2~4 被上限门禁误拦
            _used = _devices_used_in_command_queue(strArrayTest)
            _dc_all = {
                "dc1": globals().get("dc1_controller"),
                "dc2": globals().get("dc2_controller"),
                "dc3": globals().get("dc3_controller"),
                "dc4": globals().get("dc4_controller"),
            }
            _dc_used = {
                k: v
                for k, v in _dc_all.items()
                if k.upper() in _used or k in _used
            }
            _ok_lim, _reason_lim = evaluate_controllers_output_limits_gate(
                ac_controller=globals().get("ac_controller") if "AC" in _used else None,
                dc_controllers=_dc_used,
                ac_brand=globals().get("_ac_current_brand"),
                dc_brands=map_per_dc_factor_to_brands(globals().get("per_dc_factor")),
            )
            if not _ok_lim:
                msg = _reason_lim or "输出上限检查未通过"
                ui.textEdit_ReturnMessage.append("[开始试验] " + msg)
                logger.info("输出上限门禁拦截: %s", msg)
                box = QMessageBox(None)
                box.setIcon(QMessageBox.Warning)
                box.setWindowTitle("输出上限")
                box.setText(msg)
                box.setWindowFlags(box.windowFlags() | Qt.WindowStaysOnTopHint)
                box.exec_()
                return
        except Exception as _lim_exc:
            print(f"[RunProject] 输出上限门禁跳过: {_lim_exc}", flush=True)

        ui.textEdit_ReturnMessage.append(f"[开始试验] 设备校验通过，开始执行「{currentSecond}」...")
        # 第一次（及之后）成功启动：把本试验 UI 参数落到本地，与设备页隔离
        try:
            from utils.test_ui_preset import snapshot_and_save_test_preset

            _ui_obj = None
            _map = getattr(ui, "_auto_test_dialogs", None) or globals().get(
                "_auto_test_dialogs", {}
            )
            _pair = _map.get(currentSecond) if _map else None
            if _pair:
                _dlg, _ui_obj = _pair
                if hasattr(_ui_obj, "ensure"):
                    _dlg, _ui_obj = _ui_obj.ensure()
                elif hasattr(_dlg, "ensure"):
                    _dlg, _ui_obj = _dlg.ensure()
            if _ui_obj is not None:
                _path = snapshot_and_save_test_preset(currentSecond, _ui_obj)
                ui.textEdit_ReturnMessage.append(
                    f"[开始试验] 已保存本试验参数到本地：{_path}"
                )
        except Exception as _save_preset_exc:
            print(f"[RunProject] save test preset skip: {_save_preset_exc}", flush=True)
        # ── DEWETRON 模式：必须先完成采集预处理，再放行执行线程 ──
        print(f"[RunProject] is_dewetron={is_dewetron}, dewetron_collector={'存在' if dewetron_collector else 'None'}")
        if is_dewetron:
            if dewetron_collector is None:
                QMessageBox.warning(None, "连接错误", "DEWETRON采集器未初始化，请重新连接设备")
                return
            print(f"[RunProject] 调用 _prepare_dewetron_collector({currentSecond})")
            if not _prepare_dewetron_collector(currentSecond):
                QMessageBox.warning(None, "准备失败", "DEWETRON采集准备失败，试验未启动")
                return

        try:
            from utils.iot_local_run import detach_previous_job_for_fresh_start

            detach_previous_job_for_fresh_start()
        except Exception as _detach_exc:
            print(f"[RunProject] 摘掉上一单任务号跳过: {_detach_exc}", flush=True)
        _init_run_progress_plan(currentSecond, status="进行中")
        _emit_run_progress(
            status="进行中",
            cmd_index=0,
            cmd_total=len(strArrayTest) if strArrayTest else 0,
            persist=True,
        )
        _update_project_status(currentSecond, "进行中")
        strTestFlag = "1"
        _local_widgets = None
        _local_run_cmds = None
        try:
            # 全实验类型：采集当前 Dialog → prefs + 本地开测登记 Blockly
            from utils.iot_ui_handoff import (
                collect_widgets_for_project,
                persist_current_project_prefs,
            )
            from utils.iot_run_upload import snapshot_run_commands

            _svc = globals().get("_iot_ui_handoff_svc")
            n_w = persist_current_project_prefs(currentSecond, handoff_svc=_svc)
            _local_widgets = collect_widgets_for_project(currentSecond, handoff_svc=_svc) or None
            try:
                _local_run_cmds = snapshot_run_commands(globals().get("strArrayTest") or [])
            except Exception:
                _local_run_cmds = None
            if n_w:
                print(f"[RunProject] 已上报实验参数 {n_w} 项 → IOT", flush=True)
            if _local_run_cmds:
                print(f"[RunProject] 本局实际步骤 {len(_local_run_cmds)} 条一并上报", flush=True)
        except Exception as _prefs_exc:
            print(f"[RunProject] 实验参数上报跳过: {_prefs_exc}", flush=True)
        try:
            from utils.iot_local_run import notify_local_run_started

            notify_local_run_started(
                currentSecond,
                widgets=_local_widgets,
                run_commands=_local_run_cmds,
            )
        except Exception as _iot_reg_exc:
            print(f"[RunProject] IOT 本地登记跳过: {_iot_reg_exc}", flush=True)

