def DCGetIVValueFunction(strVmp,strImp,strVoc,strIsc,strPF,DCNumber):
    global ArrayfDCCurrValue, per_dc_factor, command_list_DC, bluesight_stc_params
    # 兼容功率百分比输入格式：
    # - "80" / "80%" / "80 %"
    # - "0.8"（按 80% 处理）
    def _parse_percent(v):
        if v is None:
            raise ValueError("percent is None")
        vs = str(v).strip()
        if vs.endswith('%'):
            vs = vs[:-1].strip()
        p = float(vs)
        # 兼容 0~1 的小数写法（0.8 -> 80%）
        if 0 < p <= 1:
            p *= 100.0
        return p

    dc_type = ""
    dc_type = per_dc_factor.get(str(DCNumber))
    # 厂家未识别时不再静默按致茂 IVC 生成，避免误发到蓝点/爱科；返回 "3" 由调用方提示。
    if not dc_type or dc_type not in ("Chroma", "Keysight", "Itech", "Bluesight"):
        try:
            _append_debug_log(
                f"[DCGetIVValueFunction][block] unknown dc_type={dc_type!r} for DC{DCNumber}, refuse Chroma IVC fallback"
            )
        except Exception:
            pass
        return "3"

    def _validate_iv_points(f_vmp, f_imp, f_voc, f_isc):
        """校验 SAS/IV 曲线四点。非法时返回错误码，合法返回 None。

        返回:
        - "1": 赋值错误（空值/非正/Imp>=Isc/Vmp>=Voc 等，会导致 log 域错误）
        - "2": 电流超直流源上限（由调用方在缩放后检查）
        - None: 通过
        """
        try:
            if min(f_vmp, f_imp, f_voc, f_isc) <= 0:
                return "1"
            # Chroma/Keysight 公式含 log(1 - Imp/Isc)，必须 Imp < Isc
            if f_imp >= f_isc:
                return "1"
            # 同理 Vmp 必须严格小于 Voc
            if f_vmp >= f_voc:
                return "1"
            # Imp 太接近 Isc 时 C1→0，后续 log 仍可能域错误
            if f_imp / f_isc >= 0.999:
                return "1"
            if f_vmp / f_voc >= 0.999:
                return "1"
        except Exception:
            return "1"
        return None

    if dc_type and dc_type == "Chroma":
        print(f"dc_type--{dc_type}")
        DCParArray = ["" for ii in range(128)]
        DCArray = [["" for ii in range(128)] for jj in range(2)]
        strDCArray = [["" for ii in range(128)] for jj in range(2)]
        strArrayIVValue = []
        try:
            fDCVmp = float(strVmp)
            fDCImp = float(strImp)
            fDCVoc = float(strVoc)
            fDCIsc = float(strIsc)
            fPf = _parse_percent(strPF)

        except Exception as e:
            return "1"
        else:
            fPf = 0.01 * fPf
            fDCIsc = fDCIsc * fPf
            fDCImp = fDCImp * fPf

            if ArrayfDCCurrValue[int(DCNumber)] <= fDCIsc:
                return "2"

            bad = _validate_iv_points(fDCVmp, fDCImp, fDCVoc, fDCIsc)
            if bad:
                return bad

            try:
                fParC2 = (fDCVmp / fDCVoc - 1) / math.log(1 - fDCImp / fDCIsc)  # chroma公式
                fParC1 = (1 - fDCImp / fDCIsc) * math.exp(-1 * fDCVmp / (fParC2 * fDCVoc))
                print(1)
                fFF = (fDCVmp * fDCImp) / (fDCVoc * fDCIsc)
                for i in range(128):
                    DCParArray[i] = 0 + i * (1 / 127)

                for j in range(128):
                    DCArray[0][j] = round((1 - DCParArray[j]) * fDCIsc, 3)
                    strDCArray[0][j] = '%.3f' % DCArray[0][j]

                for k in range(128):
                    # 末端点 I≈Isc 时 (1-I/Isc)/C1 可能数值不稳，做保护
                    ratio = 1.0 - (DCArray[0][k] / fDCIsc)
                    inner = (ratio / fParC1) + 1.0
                    if abs(inner) < 1e-15:
                        inner = 1e-15
                    DCArray[1][k] = round(math.fabs(math.log(math.fabs(inner)) * fParC2 * fDCVoc), 3)
                    strDCArray[1][k] = '%.3f' % DCArray[1][k]

                str1 = "IVC:IT "
                str2 = "IVC:VT "
                for i in range(len(strDCArray[0])):
                    if i == 0:
                        str1 = str1 + strDCArray[0][i]
                    else:
                        str1 = str1 + "," + strDCArray[0][i]

                for i in range(len(strDCArray[1])):
                    if i == 0:
                        str2 = str2 + strDCArray[1][i]
                    else:
                        str2 = str2 + "," + strDCArray[1][i]
                print(str1)
                strArrayIVValue.append(str1)
                print(str2)
                strArrayIVValue.append(str2)
                return strArrayIVValue
            except (ValueError, ZeroDivisionError, OverflowError) as e:
                try:
                    _append_debug_log(f"[DCGetIVValueFunction][Chroma] math error DC{DCNumber}: {e}; "
                                      f"Vmp={fDCVmp}, Imp={fDCImp}, Voc={fDCVoc}, Isc={fDCIsc}")
                except Exception:
                    pass
                return "1"
    elif dc_type and dc_type == "Keysight":
        # E4360 SAS:TABL 允许 3～1024 点。1024 点约 9KB 一次 viWrite 会打掉 HiSLIP/Soft Panel
        # 导致工况机闪退；与致茂同公式改用 128 点（约 1KB）。
        _ks_n = 128
        DCParArray = ["" for ii in range(_ks_n)]
        DCArray = [["" for ii in range(_ks_n)] for jj in range(2)]
        strDCArray = [["" for ii in range(_ks_n)] for jj in range(2)]
        strArrayIVValue = []
        try:
            fDCVmp = float(strVmp)
            fDCImp = float(strImp)
            fDCVoc = float(strVoc)
            fDCIsc = float(strIsc)
            fPf = _parse_percent(strPF)

        except Exception as e:
            return "1"
        else:
            fPf = 0.01 * fPf
            fDCIsc = fDCIsc * fPf
            fDCImp = fDCImp * fPf

            bad = _validate_iv_points(fDCVmp, fDCImp, fDCVoc, fDCIsc)
            if bad:
                return bad

            try:
                fParC2 = (fDCVmp / fDCVoc - 1) / math.log(1 - fDCImp / fDCIsc)

                fParC1 = (1 - fDCImp / fDCIsc) * math.exp(-1 * fDCVmp / (fParC2 * fDCVoc))
                fFF = (fDCVmp * fDCImp) / (fDCVoc * fDCIsc)
                _den = float(_ks_n - 1) if _ks_n > 1 else 1.0
                for i in range(_ks_n):
                    DCParArray[i] = 0 + i * (1 / _den)

                for j in range(_ks_n):
                    DCArray[0][j] = round((1 - DCParArray[j]) * fDCIsc, 3)
                    strDCArray[0][j] = '%.3f' % DCArray[0][j]

                for k in range(_ks_n):
                    ratio = 1.0 - (DCArray[0][k] / fDCIsc)
                    inner = (ratio / fParC1) + 1.0
                    if abs(inner) < 1e-15:
                        inner = 1e-15
                    DCArray[1][k] = round(math.fabs(math.log(math.fabs(inner)) * fParC2 * fDCVoc), 3)
                    strDCArray[1][k] = '%.3f' % DCArray[1][k]

                str1 = "SAS:TABL1:CURR "
                str2 = "SAS:TABL1:VOLT "
                for i in range(len(strDCArray[0])):
                    if i == 0:
                        str1 = str1 + strDCArray[0][i]
                    else:
                        str1 = str1 + "," + strDCArray[0][i]

                for i in range(len(strDCArray[1])):
                    if i == 0:
                        str2 = str2 + strDCArray[1][i]
                    else:
                        str2 = str2 + "," + strDCArray[1][i]
                print(
                    f"[Keysight IV] DC{DCNumber} FF={fFF:.4f} "
                    f"volt_cmd={len(str2)}B curr_cmd={len(str1)}B pts={_ks_n}",
                    flush=True,
                )
                strArrayIVValue.append(str2)
                strArrayIVValue.append(str1)
                return strArrayIVValue
            except (ValueError, ZeroDivisionError, OverflowError) as e:
                try:
                    _append_debug_log(f"[DCGetIVValueFunction][Keysight] math error DC{DCNumber}: {e}; "
                                      f"Vmp={fDCVmp}, Imp={fDCImp}, Voc={fDCVoc}, Isc={fDCIsc}")
                except Exception:
                    pass
                return "1"
    elif dc_type and dc_type == "Itech":
        # Itech：使用 SOL:USER:* 方式写入四参数（同样按功率百分比缩放电流）
        strArrayIVValue = []
        try:
            fDCVmp = float(strVmp)
            fDCImp = float(strImp)
            fDCVoc = float(strVoc)
            fDCIsc = float(strIsc)
            fPf = _parse_percent(strPF)
        except Exception:
            return "1"
        else:
            fPf = 0.01 * fPf
            fDCIsc = fDCIsc * fPf
            fDCImp = fDCImp * fPf
            # 电流上限检查（若数组未初始化则跳过）
            try:
                if ArrayfDCCurrValue[int(DCNumber)] <= fDCIsc:
                    return "2"
            except Exception:
                pass
            bad = _validate_iv_points(fDCVmp, fDCImp, fDCVoc, fDCIsc)
            if bad:
                return bad
            strArrayIVValue.append(f"SOL:USER:VOC {fDCVoc}")
            strArrayIVValue.append(f"SOL:USER:IMP {fDCImp}")
            strArrayIVValue.append(f"SOL:USER:VMP {fDCVmp}")
            strArrayIVValue.append(f"SOL:USER:ISC {fDCIsc}")
            return strArrayIVValue
    elif dc_type and dc_type == "Bluesight":
        # 蓝点：设备页「发送曲线」写入 100% 基准 STC；各工况点再乘功率%。
        # 缓存不得按某一次 strPF 覆盖，否则 75/50/30/20 会全部沿用第一次的 Pmpp。
        # FF：优先 Soft Panel / IOT 显式填充因子。Sandia 按 0.85 拆四点后，
        # 经典 Vmp×Imp/(Voc×Isc) 常≈0.87；若反算会把用户 0.85 顶掉。
        idx = int(DCNumber)
        ff_hint = None
        try:
            if idx == 0:
                _bs = globals().get("_dc1_bs_ref")
                if isinstance(_bs, dict) and _bs.get("sp_ff") is not None:
                    ff_hint = float(_bs["sp_ff"].value())
            if ff_hint is None:
                _ui_dc = globals().get("uiDC1Setting") if idx == 0 else None
                _ff_w = getattr(_ui_dc, "textEdit_FF", None) if _ui_dc is not None else None
                if _ff_w is not None and hasattr(_ff_w, "toPlainText"):
                    _ff_txt = str(_ff_w.toPlainText() or "").strip()
                    if _ff_txt:
                        ff_hint = float(_ff_txt)
        except (TypeError, ValueError):
            ff_hint = None
        params = bluesight_stc_params.get(idx) or bluesight_stc_params.get(idx + 1) or {}
        pmpp = params.get("pmpp", 0)
        umpp = params.get("umpp", 0)
        ff = params.get("ff", 0.8)
        if ff_hint is not None and 0.25 <= ff_hint <= 0.95:
            ff = ff_hint
        if pmpp <= 0 or umpp <= 0:
            from utils.guochan_sim_matrix import bluesight_stc_from_iv
            derived = bluesight_stc_from_iv(
                strVmp, strImp, strVoc, strIsc, "100", ff=ff_hint
            )
            if derived is None:
                return "1"
            pmpp, umpp, ff = derived
            bluesight_stc_params[idx] = {"pmpp": pmpp, "umpp": umpp, "ff": ff}
        elif ff_hint is not None and 0.25 <= ff_hint <= 0.95:
            bluesight_stc_params[idx] = {"pmpp": pmpp, "umpp": umpp, "ff": ff}
        try:
            fPf = _parse_percent(strPF)
        except Exception:
            fPf = 100.0
        scale = max(fPf, 0.0) / 100.0
        pmpp_out = pmpp * scale
        if pmpp_out <= 0:
            return "1"
        return [f"BLUESIGHT:STC {pmpp_out} {umpp} {ff}"]

    # 兜底：理论上不会走到这里
    return "1"

def get_enumwindows():
    hwnd_list = {}
    def foo(hwnd, result):
        if win32gui.IsWindow(hwnd) and \
            win32gui.IsWindowEnabled(hwnd) and \
                win32gui.IsWindowVisible(hwnd):
                hwnd_list.update({hwnd: win32gui.GetWindowText(hwnd)})

    win32gui.EnumWindows(foo, 0)
    return hwnd_list


def _get_wt_exe_path():
    """从 config.ini 读取 WTViewerEfree 路径（新 UI 已无 lE_wt_path）。"""
    try:
        config = configparser.ConfigParser(interpolation=None)
        config.read('config_files/config.ini', encoding='utf-8')
        if config.has_section('PATH') and config.has_option('PATH', 'wt_exe'):
            return config['PATH']['wt_exe']
    except Exception as e:
        _append_debug_log(f"[WT] read wt_exe failed: {e}")
    return None


def _find_wtviewer_hwnd(hwnd_dict=None):
    """查找 WTViewerEfree 主窗口句柄。

    优先精确标题，其次标题包含 WTViewer，再按进程 PID 枚举。
    会跳过「数值详细设置」等子对话框。
    """
    if hwnd_dict is None:
        hwnd_dict = get_enumwindows()

    for hwnd, title in hwnd_dict.items():
        if title == 'WTViewerEfree':
            return hwnd
    for hwnd, title in hwnd_dict.items():
        if title and 'WTViewer' in title and title != '数值详细设置':
            return hwnd

    try:
        target_pids = set()
        for proc in psutil.process_iter(['pid', 'name']):
            name = proc.info.get('name') or ''
            if 'WTViewerEfree' in name:
                target_pids.add(proc.info['pid'])
        if not target_pids:
            return None

        candidates = []

        def _enum_cb(hwnd, _):
            if not win32gui.IsWindowVisible(hwnd):
                return True
            try:
                _, wpid = win32gui.GetWindowThreadProcessId(hwnd)
            except Exception:
                return True
            if wpid not in target_pids:
                return True
            title = win32gui.GetWindowText(hwnd) or ''
            if title == '数值详细设置':
                return True
            if title:
                candidates.append((hwnd, title))
            return True

        win32gui.EnumWindows(_enum_cb, None)
        for hwnd, title in candidates:
            if 'WTViewer' in title:
                return hwnd
        if candidates:
            return candidates[0][0]
    except Exception as e:
        _append_debug_log(f"[WT] find hwnd by pid failed: {e}")
    return None


def _close_wt_detail_dialogs():
    """关闭残留的「数值详细设置」窗口，避免挡住主窗或沿用旧勾选。"""
    try:
        for hwnd, title in list(get_enumwindows().items()):
            if title == '数值详细设置':
                try:
                    win32gui.PostMessage(hwnd, win32con.WM_CLOSE, 0, 0)
                    _append_debug_log(f"[WT] closed leftover detail dialog hwnd={hwnd}")
                except Exception:
                    pass
        time.sleep(0.4)
    except Exception as e:
        _append_debug_log(f"[WT] close detail dialog failed: {e}")

