def find_dialog_by_content(keyword, timeout=20):
    """
    通过检测窗口内部文本内容查找对话框
    返回: 窗口句柄(hwnd)或None
    """
    start_time = time.time()
    
    def enum_child_callback(child_hwnd, result_ref):
        """枚举子控件回调函数"""
        # 获取控件类名（静态文本通常是"Static"）
        class_name = win32gui.GetClassName(child_hwnd)
        
        # 获取控件文本内容
        text = win32gui.GetWindowText(child_hwnd)
        
        # 检查是否包含目标关键词
        if keyword in text:
            # 获取顶层父窗口句柄
            root_hwnd = win32gui.GetAncestor(child_hwnd, win32con.GA_ROOT)
            result_ref.append(root_hwnd)
            return False  # 找到后停止枚举
        return True
    
    def enum_top_callback(top_hwnd, result_ref):
        """枚举顶层窗口回调函数"""
        # 只检查可见窗口
        if win32gui.IsWindowVisible(top_hwnd):
            # 枚举该窗口的所有子控件
            win32gui.EnumChildWindows(top_hwnd, enum_child_callback, result_ref)
        return True
    
    result = []
    while time.time() - start_time < timeout:
        # 清空结果列表
        result.clear()
        
        # 枚举所有顶层窗口及其子控件
        win32gui.EnumWindows(enum_top_callback, result)
        
        # 如果找到匹配，返回第一个结果
        if result:
            return result[0]
        
        time.sleep(0.5)  # 间隔0.5秒后重试
    
    return None

def click_button_by_text(parent_hwnd, button_text):
    """查找并点击指定文本的按钮"""
    def btn_callback(btn_hwnd, result):
        if win32gui.GetClassName(btn_hwnd) == "Button":
            if button_text in win32gui.GetWindowText(btn_hwnd):
                result.append(btn_hwnd)
                return False
        return True
    
    btn_list = []
    win32gui.EnumChildWindows(parent_hwnd, btn_callback, btn_list)
    if btn_list:
        win32gui.PostMessage(btn_list[0], win32con.BM_CLICK, 0, 0)
        return True
    return False


def auto_config():
    # global cells_crood
    global setting_icon, messure_icon, messure_status, setting_status, heading_handle, param_dict,manager,ui
    # cells_crood = cell_crood
    wt_running = False

    def _wt_auto_aborted():
        return globals().get("strTestStatusFlag") == "结束"

    def _abortable_sleep(seconds):
        """分段 sleep，结束试验时可尽快返回 True。"""
        deadline = time.time() + max(0.0, float(seconds))
        while time.time() < deadline:
            if _wt_auto_aborted():
                return True
            time.sleep(min(0.2, max(0.0, deadline - time.time())))
        return _wt_auto_aborted()

    if _wt_auto_aborted():
        logger.info("[auto_config] 用户已结束试验，跳过 WTViewer 自动配置")
        return False

    def _get_child_handle_by_text(parent_hwnd, target_text, retry_times=8, retry_interval=0.5):
        """重试获取指定文本的子控件句柄，避免界面尚未渲染时直接抛异常。"""
        for attempt in range(retry_times):
            if _wt_auto_aborted():
                return None
            child_dict = {}
            win32gui.EnumChildWindows(
                parent_hwnd,
                lambda hwnd, parm: parm.update({hwnd: win32gui.GetWindowText(hwnd)}),
                child_dict
            )
            if target_text in child_dict.values():
                return list(child_dict.keys())[list(child_dict.values()).index(target_text)]
            _append_debug_log(
                f"[auto_config][wait] child '{target_text}' not found, attempt={attempt + 1}/{retry_times}"
            )
            if _abortable_sleep(retry_interval):
                return None
        return None
    wt_guiconnect = True
    for proc in psutil.process_iter(['pid', 'name']):
        try:
            if 'WTViewerEfree' in proc.info['name']:
                wt_running = True
                print(f"WTViewerEfree 已在运行 (PID: {proc.info['pid']})")
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass

    # 主逻辑
    if not wt_running:
        # 创建配置解析器对象
        config = configparser.ConfigParser(interpolation=None)
        # 读取INI文件（文件路径可以是相对路径或绝对路径）
        config.read('config_files/config.ini', encoding='utf-8')
        if config.has_section('PATH'):
            wt_path = config['PATH']['wt_exe']
        else:
            QMessageBox.warning(None,"wt路径错误","请检查config.ini文件")
            return False
        print(f"正在启动 WTViewerEfree: {wt_path}")
        os.startfile(wt_path)
        
        # 等待主窗口出现（根据实际情况调整）
        time.sleep(3)
        pyautogui.press('enter')
        
        # 检测"设备未找到"对话框（通过内部文本内容，带20秒超时）
        print("检测'设备未找到'对话框（通过内部文本）...")
        dialog_hwnd = find_dialog_by_content("设备未找到", timeout=20)
        
        if dialog_hwnd:
        
            # 可选：获取对话框标题（调试用）
            dialog_title = win32gui.GetWindowText(dialog_hwnd)
            print(f"对话框标题: {dialog_title}")
            
            click_button_by_text(dialog_hwnd, "确定")
            wt_guiconnect = False
            QMessageBox.warning(None,"连接错误","wt连接存在异常")
            return False
        else:
            pass
    heading_handle = get_enumwindows()
    # 先关掉残留的「数值详细设置」，否则主窗标题可能匹配不到，且会沿用旧勾选
    _close_wt_detail_dialogs()
    heading_handle = get_enumwindows()

    h = _find_wtviewer_hwnd(heading_handle)
    if h is None:
        wt_path = _get_wt_exe_path()
        if not wt_path:
            QMessageBox.warning(None, "wt路径错误", "请检查 config_files/config.ini 中 [PATH] wt_exe")
            _append_debug_log("[auto_config][error] wt_exe missing in config.ini")
            return False
        print(f"未找到 WTViewerEfree 窗口，尝试启动: {wt_path}")
        _append_debug_log(f"[auto_config] launch WTViewerEfree: {wt_path}")
        try:
            os.startfile(wt_path)
        except Exception as e:
            _append_debug_log(f"[auto_config][error] startfile failed: {e}")
            return False
        for attempt in range(12):
            time.sleep(0.5)
            heading_handle = get_enumwindows()
            h = _find_wtviewer_hwnd(heading_handle)
            if h is not None:
                break
            _append_debug_log(f"[auto_config][wait] WTViewer hwnd, attempt={attempt + 1}/12")
        if h is None:
            msg = "未找到 WTViewerEfree 窗口，数值详细设置未写入"
            print(msg)
            _append_debug_log(f"[auto_config][error] {msg}")
            try:
                ui.textEdit_ReturnMessage.append(f"[WT配置] {msg}")
            except Exception:
                pass
            return False

    # 统一用找到的主窗句柄；保证后续 .index('WTViewerEfree') 兼容路径也能命中
    heading_handle[h] = 'WTViewerEfree'

    if h is not None:
        headle_now_list = {}
        win32gui.ShowWindow(h, win32con.SW_SHOWMAXIMIZED)
        win32gui.SetForegroundWindow(h)
        left_wtv, top_wtv, right_wtv, bottom_wtv = win32gui.GetWindowRect(h)
        print(left_wtv, top_wtv, right_wtv, bottom_wtv)
        # setting_icon = (left_wtv + 8 + 43 ,top_wtv + 8 + 7 + 23 + 81 + 27)
        # messure_icon = (left_wtv + 8 + 43 ,top_wtv + 8 + 7 + 23 + 81 + 81 + 27)
        setting_icon = (left_wtv + 51 ,top_wtv + 146)
        messure_icon = (left_wtv + 51 ,top_wtv + 227)

        param_dict = {}
        logger.info('子句柄清空！')
        win32gui.EnumChildWindows(h, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), param_dict)
        logger.info('重新获取子句柄！')
        _child_texts = [t for t in param_dict.values() if t]
        _branch = (
            '开始在线连接' if '开始在线连接' in param_dict.values()
            else '停止在线连接' if '停止在线连接' in param_dict.values()
            else '数值页已开' if ('数值列表' in param_dict.values() and '数值' in param_dict.values())
            else '其它'
        )
        logger.info(f"[auto_config] WTViewer 分支={_branch}, 子控件={_child_texts[:40]}")
        try:
            ui.textEdit_ReturnMessage.append(
                f"[WT配置] 正在配置 WTViewer（{_branch}），请勿操作鼠标，电源命令会在这之后才发出"
            )
        except Exception:
            pass

        def _wt_auto_aborted():
            return globals().get("strTestStatusFlag") == "结束"

        if _wt_auto_aborted():
            logger.info("[auto_config] 用户结束试验，停止 WTViewer 配置")
            return False

        if '开始在线连接' in param_dict.values():
            messure_handle_dict = {}
            key_child_start = list(param_dict.keys())[list(param_dict.values()).index('开始在线连接')]
            left, top, right, bottom = win32gui.GetWindowRect(key_child_start) 
            pyautogui.moveTo(left + (right - left) / 2, top + (bottom - top) / 2, duration=1)
            if _wt_auto_aborted():
                return False
            pyautogui.click()
            # 等按钮从「开始在线连接」变成其它（连上后一般是「停止在线连接」）
            connect_ok = False
            param_list1 = {}
            wait_deadline = time.time() + 20
            while time.time() < wait_deadline:
                if _wt_auto_aborted():
                    logger.info("[auto_config] 用户结束试验，停止等待 WTViewer 在线连接")
                    return False
                win32gui.EnumChildWindows(h, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), param_list1)
                btn_text = param_list1.get(key_child_start, '')
                if btn_text and btn_text != '开始在线连接':
                    connect_ok = True
                    break
                if '停止在线连接' in param_list1.values():
                    connect_ok = True
                    break
                time.sleep(0.5)
            if not connect_ok:
                msg = (
                    "WTViewer 点击「开始在线连接」后 20 秒按钮未变化。"
                    "请先在 WTViewer 手动连上仪表（按钮应变为「停止在线连接」），"
                    "关掉残留的「数值详细设置」，再点开始。"
                    "若 AutoTest 已占用 WT 的 10001 端口，请先在 Viewer 连上仪表，或确认 Viewer 已在线后再开始。"
                )
                logger.info(f"[auto_config][error] {msg}")
                _append_debug_log(f"[auto_config][error] {msg}")
                try:
                    ui.textEdit_ReturnMessage.append(f"[WT配置] {msg}")
                except Exception:
                    pass
                return False
            if _abortable_sleep(1):
                return False
            pyautogui.moveTo(setting_icon[0], setting_icon[1], duration=0.5)
            pyautogui.doubleClick()
            if _abortable_sleep(2):
                return False
            pyautogui.click()
            if _abortable_sleep(2):
                return False
            if _wt_auto_aborted():
                return False
            setting_set(h)
            if _wt_auto_aborted():
                return False
            pyautogui.moveTo(messure_icon[0], messure_icon[1], duration=0.5)
            pyautogui.doubleClick()
            if _abortable_sleep(2):
                return False
            pyautogui.click()
            if _abortable_sleep(2):
                return False
            messure_handle_now = _get_child_handle_by_text(h, '数值')
            if messure_handle_now is None:
                _append_debug_log("[auto_config][error] child '数值' not found after reconnect flow")
                return False
            if _wt_auto_aborted():
                return False
            messured_set(messure_handle_now)
            win32gui.EnumChildWindows(h, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), param_list1)           
        elif '停止在线连接' in param_dict.values():
            messure_handle_dict = {}
            if _wt_auto_aborted():
                return False
            pyautogui.moveTo(setting_icon[0], setting_icon[1], duration=0.5)
            pyautogui.doubleClick()
            if _abortable_sleep(2):
                return False
            pyautogui.click()
            if _abortable_sleep(2):
                return False
            if _wt_auto_aborted():
                return False
            setting_set(h)
            if _wt_auto_aborted():
                return False
            pyautogui.doubleClick(messure_icon[0], messure_icon[1], duration=0.5) 
            pyautogui.click()
            if _abortable_sleep(2):
                return False
            pyautogui.click()
            if _abortable_sleep(2):
                return False
            messure_handle_now = _get_child_handle_by_text(h, '数值')
            if messure_handle_now is None:
                _append_debug_log("[auto_config][error] child '数值' not found in already-connected flow")
                return False
            if _wt_auto_aborted():
                return False
            messured_set(messure_handle_now)


            
        elif "数值列表" not in param_dict.values() and "数值" not in param_dict.values():
            messure_handle_dict = {}
            if _wt_auto_aborted():
                return False
            if setting_status == '':
                key_child_setting = list(param_dict.keys())[list(param_dict.values()).index('接线方式')]
                setting_set(h)
            if _wt_auto_aborted():
                return False
            pyautogui.moveTo(messure_icon[0], messure_icon[1], duration=0.5)
            pyautogui.doubleClick()
            if _abortable_sleep(2):
                return False
            pyautogui.click()
            if _abortable_sleep(2):
                return False
            key_child_messure = _get_child_handle_by_text(h, '数值')
            if key_child_messure is None:
                _append_debug_log("[auto_config][error] child '数值' not found in open-measure-page flow")
                return False
            left, top, right, bottom = win32gui.GetWindowRect(key_child_messure)
            if _wt_auto_aborted():
                return False
            messured_set(key_child_messure)
        elif "数值列表" in param_dict.values() and "数值" in param_dict.values():
            # 分支含义：当前 WT 主界面里已经同时存在"数值列表"和"数值"控件
            # 说明测量相关页面基本已打开，只需要判断"设置页参数是否已配置"即可。

            if _wt_auto_aborted():
                return False

            # setting_status == ''：代表"接线方式/更新率"等设置页参数还没做过
            if setting_status == '':
                messure_handle_dict = {}

                # 1) 先切到"设置"页签（左侧导航图标）
                # moveTo + doubleClick + click 是为了提高点击稳定性（不同机型/窗口焦点下，单击可能不生效）
                pyautogui.moveTo(setting_icon[0], setting_icon[1], duration=0.5)
                pyautogui.doubleClick()
                if _abortable_sleep(2):
                    return False
                pyautogui.click()
                if _abortable_sleep(2):
                    return False

                # 2) 执行设置页自动配置：接线方式、更新率等（按 config_dict 写入）
                if _wt_auto_aborted():
                    return False
                setting_set(h)

                # 3) 再切回"测量/数值"页签
                if _wt_auto_aborted():
                    return False
                pyautogui.moveTo(messure_icon[0], messure_icon[1], duration=0.5)
                pyautogui.doubleClick()
                if _abortable_sleep(2):
                    return False
                pyautogui.click()
                if _abortable_sleep(2):
                    return False

                # 4) 重新枚举子控件，拿到"数值"控件的最新句柄
                #    重新获取是为了避免界面切页后句柄失效/变化
                messure_handle_now = _get_child_handle_by_text(h, '数值')
                if messure_handle_now is None:
                    _append_debug_log("[auto_config][error] child '数值' not found after setting page config")
                    return False
            else:
                # setting_status != ''：说明设置页之前已经配过
                # 直接复用当前枚举出来的"数值"句柄，减少重复切页动作
                messure_handle_now = _get_child_handle_by_text(h, '数值')
                if messure_handle_now is None:
                    _append_debug_log("[auto_config][error] child '数值' not found in direct-use flow")
                    return False

            # 5) 进入"数值详细设置"流程：
            #    - 打开右键菜单中的"数值详细设置"
            #    - 配置测量项勾选、时间、保存文件名等
            if _wt_auto_aborted():
                return False
            messured_set(messure_handle_now)

def setting_set(h):
    """
    作用：
    - 在 WT 的"设置"页里自动配置接线方式与更新率。
    - 配置来源是全局 `config_dict`；不同机型切片范围不同。

    参数：
    - h: WT 主窗口句柄（用于枚举子控件）

    说明：
    - 本函数通过"相对坐标 + 鼠标点击"驱动 UI。
    - 如果界面布局、缩放或版本变化，坐标和步长(step)可能要重新校准。
    """
    global setting_icon, messure_icon, messure_status, setting_status, config_dict, wt_type

    # 兼容"上位机WT配置"为**空字符串/空字典**的场景：
    # - 这种情况下用户期望仅完成 WT 连接并继续后续宏回放/测量流程
    # - 不应进入设置页去解析/点击接线方式、更新率等参数
    if not config_dict:
        setting_status = '1'
        _append_debug_log("[setting_set] empty config_dict -> skip setting page config")
        return

    # connect_mode：从 config_dict 中提取"设置页"对应配置项
    # 约定：最后一项用于"更新率"，前面若干项用于"接线方式"
    connect_mode = []
    # parm_dict_set：当前 WT 主窗口子控件文本缓存（用于按文本找控件）
    parm_dict_set = {}

    # 不同 WT 机型在 config_dict 中的字段位置不同，所以切片范围不同
    if wt_type == 'WT3000':
        for i in list(config_dict.values())[1:8]:
            connect_mode.append(i)
    elif wt_type == 'WT1800' or wt_type == 'WT1806E':
        for i in list(config_dict.values())[1:9]:
            connect_mode.append(i)
    elif wt_type == 'WT5000':
        for i in list(config_dict.values())[1:6]:
            connect_mode.append(i)

    # 若提取不到任何"设置页"参数，同样跳过配置（避免 connect_mode[-1] 等越界）
    if not connect_mode:
        setting_status = '1'
        _append_debug_log("[setting_set] connect_mode empty -> skip setting page config")
        return

    # 获取主窗口子控件文本（用于判断"接线方式/更新率"是否可见）
    win32gui.EnumChildWindows(h, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), parm_dict_set)

    # 下拉项逐行高度经验步长（接线方式区域）
    step = 14

    # =========================
    # 第一段：配置"接线方式"
    # 条件：窗口里存在"接线方式"控件且尚未完成配置(setting_status != '1')
    # =========================
    if "接线方式" in parm_dict_set.values() and setting_status != '1':
        step = 14

        # 通过文本"接线方式"定位到该区域，得到该控件矩形
        key_child_setting = list(parm_dict_set.keys())[list(parm_dict_set.values()).index('接线方式')]
        left, top, right, bottom = win32gui.GetWindowRect(key_child_setting)

        # local_per：每个接线方式下拉框的点击基准坐标（相对接线方式控件）
        # 不同机型接线方式项数量不同，坐标数量也不同
        if wt_type == 'WT1800' or wt_type == 'WT1806E':
            local_per = [(left + 116, top + 104), (left + 205, top + 104),
                (left + 116, top + 130), (left + 205, top + 130),
                (left + 116, top + 156), (left + 205, top + 156),
                (left + 196, top + 182)]
        elif wt_type == 'WT3000':
            local_per = [(left + 116, top + 104), (left + 205, top + 104),
                (left + 116, top + 130), (left + 205, top + 130),
                (left + 195, top + 156), (left + 196, top + 182)]
        elif wt_type == 'WT5000':
            local_per = [(left + 116, top + 104), (left + 205, top + 104),
                (left + 116, top + 130), (left + 205, top + 130)]

        # 先点击"接线方式"标题区域，使该区域获得焦点
        pyautogui.moveTo(left + (right - left) / 2, top + (bottom - top) / 2, duration=0.5)
        pyautogui.click()

        time.sleep(1)

        # 逐个配置接线项：遍历到 len(connect_mode)-1，最后一位预留给"更新率"
        for j in range(len(connect_mode) - 1):
            param_warn_info_win_dict = {}

            # 空字符串表示该项不改，跳过
            if connect_mode[j] != "":
                handle_now_dict = {}

                # 1) 点击第 j 个下拉框
                pyautogui.moveTo(local_per[j][0], local_per[j][1], duration=0.5)
                pyautogui.click()
                time.sleep(1)

                # 2) 根据配置值计算列表偏移并点击目标选项
                chose_step = (int(connect_mode[j]) + 1) * step
                pyautogui.moveTo(local_per[j][0], local_per[j][1] + chose_step, duration=0.5)
                pyautogui.click()
                time.sleep(2)

                # 3) 处理弹窗告警："不能指定接线的模块。"
                handle_now_dict = get_enumwindows()
                param_warn_handle = list(handle_now_dict.keys())[list(handle_now_dict.values()).index('WTViewerEfree')]
                win32gui.EnumChildWindows(param_warn_handle, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), param_warn_info_win_dict)
                if '确定' in param_warn_info_win_dict.values() and '不能指定接线的模块。' in param_warn_info_win_dict.values():
                    handle_sure = list(param_warn_info_win_dict.keys())[list(param_warn_info_win_dict.values()).index('确定')]
                    left_warn, top_warn, right_warn, bottom_warn = win32gui.GetWindowRect(handle_sure)
                    pyautogui.moveTo(left_warn + (right_warn - left_warn) / 2, top_warn + (bottom_warn - top_warn) / 2, duration=0.5)
                    pyautogui.click()
                else:
                    # 无告警则给界面一点稳定等待时间
                    pyautogui.sleep(3)

            # 循环最后一项时，补点一次"接线方式"区域，帮助收起下拉并稳定焦点
            if j == len(connect_mode) - 2:
                pyautogui.moveTo(left + (right - left) / 2, top + (bottom - top) / 2, duration=0.5)
                pyautogui.click()

    # =========================
    # 第二段：配置"更新率"
    # 条件：窗口里存在"更新率"控件且尚未完成配置(setting_status != '1')
    # =========================
    if globals().get("strTestStatusFlag") == "结束":
        logger.info("[setting_set] 用户结束试验，跳过更新率配置")
        return
    if "更新率" in parm_dict_set.values() and setting_status != '1':
        # 更新率下拉列表的经验步长与接线方式略不同
        step = 13

        # 仍以"接线方式"控件为基准推算更新率区域坐标
        key_child_setting = list(parm_dict_set.keys())[list(parm_dict_set.values()).index('接线方式')]
        left, top, right, bottom = win32gui.GetWindowRect(key_child_setting)

        # 更新率下拉框基准点
        left1, top1, = left + 142, top + 164

        # WT5000 与其它机型在更新率选项列表位置上偏移不同
        if wt_type == 'WT5000':
            local_per = (left1, top1 + 62)
        else:
            local_per = (left1, top1 + 31)

        # 先点击更新率区域
        pyautogui.moveTo(left1, top1, duration=0.5)
        pyautogui.click()
        time.sleep(0.5)

        param_warn_info_win_dict = {}
        handle_now_dict = {}

        # connect_mode[-1] 约定为更新率配置值
        if connect_mode and connect_mode[-1] != "":
            # 1) 展开更新率下拉
            pyautogui.moveTo(local_per[0], local_per[1], duration=0.5)
            pyautogui.click()
            time.sleep(0.2)

            # 2) 按步长选择目标更新率
            chose_step = (int(connect_mode[-1]) + 1) * step
            pyautogui.moveTo(local_per[0], local_per[1] + chose_step, duration=0.5)
            pyautogui.click()
            pyautogui.sleep(3)

            # 3) 同样处理"不能指定接线的模块。"告警
            handle_now_dict = get_enumwindows()
            param_warn_handle = list(handle_now_dict.keys())[list(handle_now_dict.values()).index('WTViewerEfree')]
            win32gui.EnumChildWindows(param_warn_handle, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), param_warn_info_win_dict)
            if '确定' in param_warn_info_win_dict.values() and '不能指定接线的模块。' in param_warn_info_win_dict.values():
                # 这里原代码取"确认"按钮（与上段"确定"不一致），保留原逻辑
                handle_sure = list(param_warn_info_win_dict.keys())[list(param_warn_info_win_dict.values()).index('确认')]
                left_warn, top_warn, right_warn, bottom_warn = win32gui.GetWindowRect(handle_sure)
                pyautogui.moveTo(left_warn + (right_warn - left_warn) / 2, top_warn + (bottom_warn - top_warn) / 2, duration=0.5)
                pyautogui.click()

            # 4) 再点一下更新率区域，帮助收起下拉并锁定状态
            pyautogui.moveTo(left1, top1, duration=0.5)
            pyautogui.click()

    # 标记设置页配置完成，后续流程可按"已配置"分支走
    setting_status = '1'

def messured_set(messure_handle):
    """
    作用：
    - 打开 WT 的"数值详细设置"窗口
    - 配置"详细参数页"(左页签)与"测量项目页"(右页签)
    - 按项目配置测量时长、自动保存路径、文件名、测量项勾选等
    - 最后点击"确认/应用"让配置生效

    参数：
    - messure_handle: WT 主界面里"数值/数值列表"控件的句柄

    注意：
    - 本函数大量依赖屏幕坐标+鼠标点击，分辨率/缩放/界面布局变化会影响稳定性
    - 通过一组全局状态位控制"首次配置"与"每轮仅更新局部参数"
    """
    # --- 全局状态/坐标/配置数据 ---
    global setting_icon, messure_icon, messure_status, setting_status, messsure_deatil_cofig, messure_project_cofig
    global cells_coord, test_time_list, save_file_name, save_file_name,\
        config_dict, check_project_status, START_AND_STOP_COORD, wt_type, auto_save_file, test_program, per_test_time_list
    global now_save_file
    # 过欠压_过欠频第一组测试时间设置状态，0: 首轮时间未写入；1: 已写入
    global volt_fz_first_status

    # 兼容"上位机WT配置"为**空字符串/空字典**的场景：
    # - Upper_WT_Config 可能只用于触发 WT 连接/置前，而不希望改动任何"数值详细设置/测量项目"的勾选
    # - 原逻辑会先清理(批量点击)测量项目区；若 config_dict 为空则不会再勾回来，导致"全部反选/清空"
    # - 因此这里直接跳过 UI 配置，但把状态位置为已就绪，避免 run_loop 的恢复逻辑反复调用本函数
    if not config_dict:
        messsure_deatil_cofig = '1'
        messure_project_cofig = '1'
        messure_status = '1'
        _append_debug_log("[messured_set] empty config_dict -> skip measure detail/project config")
        return

    # 当前窗口句柄/控件文本缓存
    handle_now_dict = {}
    parm_dict_set = {}
    # WT配置中的谐波次数"开始/结束"下拉项索引位置（不同机型不同）
    i_list = []

    # 取"数值"控件的屏幕矩形框，用于后续鼠标定位
    left, top, right, bottom = win32gui.GetWindowRect(messure_handle)
    print(left, top, right, bottom)

    # 在"数值"区域中心右键，调出上下文菜单（目标：打开"数值详细设置"）
    pyautogui.moveTo(left + (right - left) / 2, top + (bottom - top) / 2, duration=0.5)
    pyautogui.rightClick()

    # 枚举所有顶层窗口，检查"数值详细设置"是否已经弹出
    handle_now_dict = get_enumwindows()
    # 成功找到"数值详细设置"窗口后，进入自动配置流程
    if "数值详细设置" in handle_now_dict.values():
        # 获取"数值详细设置"窗口句柄
        deatil_messure_set_handle = list(handle_now_dict.keys())[list(handle_now_dict.values()).index('数值详细设置')]
        # 窗口恢复并置前，避免被其它窗口遮挡导致点击失败
        win32gui.ShowWindow(deatil_messure_set_handle, win32con.SW_RESTORE)
        win32gui.SetForegroundWindow(deatil_messure_set_handle)

        # 读取详细设置窗口的位置；后续所有点击都基于这个窗口的相对坐标
        left, top, right, bottom = win32gui.GetWindowRect(deatil_messure_set_handle)
        # 左页签（详细参数）与右页签（测量项目）的大致点击坐标
        t1 = (left + 40, top + 43)
        t2 = (left + 100, top + 43)

        # connect_messure_mode: 从配置字典切片出来的"测量设置参数序列"
        # 注意：静态 Cos 会往 config_dict 末尾注入 wt_merge_* 元数据，这些不是 UI 勾选项，
        # 必须剔除，否则会按坐标点击越界 → IndexError，表现为勾完项目不点确认、也不自动开始。
        connect_messure_mode = []
        _wt_ui_meta_prefixes = ('wt_merge_',)
        if wt_type == 'WT3000':
            _slice_start = 8
        elif wt_type == 'WT1800' or wt_type == 'WT1806E':
            _slice_start = 9
        elif wt_type == 'WT5000':
            _slice_start = 6
        else:
            _slice_start = 0
        for _k, _v in list(config_dict.items())[_slice_start:]:
            if isinstance(_k, str) and _k.startswith(_wt_ui_meta_prefixes):
                continue
            connect_messure_mode.append(_v)

        # =========================
        # 第一部分：详细参数页（左页签）
        # messsure_deatil_cofig == '' 表示"首次完整配置"
        # =========================
        if messsure_deatil_cofig == '':
            # config_1 对应"详细参数页"的前 6 个配置项
            config_1 = connect_messure_mode[:6]

            # 点击左页签（详细参数）
            pyautogui.moveTo(t1[0], t1[1], duration=0.5)
            pyautogui.click()

            # 逐项写入详细参数
            for i in range(len(config_1)):
                # 空字符串表示该项不配置，直接跳过
                if config_1[i] != '':
                    # i==0: 下拉项（例如接线相关/模式项）
                    if i == 0:
                        pyautogui.moveTo(cells_coord[1][i][0] + left, cells_coord[1][i][1] + top, duration=0.5)
                        pyautogui.click()
                        # 不同选项在下拉列表里的偏移距离不同，这里按历史经验值处理
                        if int(config_1[i]) == 0:
                            pyautogui.moveTo(cells_coord[1][i][0] + left, cells_coord[1][i][1] + top + 18, duration=0.5)
                            pyautogui.click()
                        elif int(config_1[i]) == 4:
                            pyautogui.moveTo(
                                cells_coord[1][i][0] + left,
                                cells_coord[1][i][1] + top + 20 + (int(config_1[i]) + 1) * 11, duration=0.5)
                            pyautogui.click()
                        else:
                            pyautogui.moveTo(
                                cells_coord[1][i][0] + left,
                                cells_coord[1][i][1] + top + 20 + int(config_1[i]) * 11, duration=0.5)
                            pyautogui.click()

                    # i==1: 另一类下拉参数
                    if i == 1:
                        pyautogui.moveTo(cells_coord[1][i][0] + left, cells_coord[1][i][1] + top, duration=0.5)
                        pyautogui.click()
                        if int(config_1[i]) == 0:
                            pyautogui.moveTo(cells_coord[1][i][0] + left, cells_coord[1][i][1] + top + 20, duration=0.5)
                            pyautogui.click()
                        else:
                            pyautogui.moveTo(
                                cells_coord[1][i][0] + left,
                                cells_coord[1][i][1] + top + 20 + int(config_1[i]) * 11, duration=0.5)
                            pyautogui.click()

                    # i==2: 测量时长（hh:mm:ss）
                    if i == 2:
                        # 当前这行原逻辑里把 int 和字符串比较，条件几乎不会成立（保留原行为，不在本次注释改动中修）
                        if int(config_1[i-1]) == '0' or int(config_1[i-1]) == '2':
                            continue
                        else:
                            # 特殊项目（过欠压/过欠频）首轮时长取 per_test_time_list[0]
                            if test_program[0][0] == '7' or test_program[0][0] == '11':
                                first_test_time = float(per_test_time_list[0])
                                m, s = divmod(first_test_time, 60)
                                h, m = divmod(m, 60)
                                test_time_list = [int(h), int(m), int(s)]
                                volt_fz_first_status = 0
                            else:
                                # 普通项目直接从配置字符串（如 00:05:00）解析
                                test_time_list = [int(value) for value in config_1[i].split(':')]

                            # 依次写入 时/分/秒 三个输入框
                            for j in range(len(test_time_list)):
                                pyautogui.moveTo(cells_coord[1][i][j][0] + left, cells_coord[1][i][j][1] + top, duration=0.5)
                                pyautogui.doubleClick()
                                pyautogui.typewrite(str(test_time_list[j]))
                                pyautogui.sleep(0.2)

                    # i==3: 保存路径
                    if i == 3:
                        file_locl = config_1[i]
                        pyautogui.moveTo(cells_coord[1][i][0] + left, cells_coord[1][i][1] + top, duration=0.5)
                        pyautogui.click()
                        pyautogui.hotkey('ctrl', 'a', interval=0.5)
                        pyperclip.copy(rf'{file_locl}')
                        pyautogui.hotkey('ctrl', 'V', interval=0.5)

                    # i==4: 自动保存勾选（仅在未勾选状态时操作）
                    if i == 4 and auto_save_file == '':
                        pyautogui.moveTo(cells_coord[1][i][0] + left, cells_coord[1][i][1] + top, duration=0.5)
                        pyautogui.click()
                        auto_save_file = '0'

                    # i==5: 文件名列表，首次写入第一个文件名
                    if i == 5 and auto_save_file == '0':
                        file_name_list = [value for value in config_1[i].split(',')]
                        pyautogui.moveTo(cells_coord[1][i][0] + left, cells_coord[1][i][1] + top, duration=0.5)
                        pyautogui.click()
                        pyautogui.hotkey('ctrl', 'a', interval=0.5)
                        pyperclip.copy(f'{file_name_list[0]}')
                        pyautogui.hotkey('ctrl', 'V', interval=0.5)

            # 标记：详细参数页首次配置已完成
            messsure_deatil_cofig = '1'

        # =========================
        # 第二部分：测量项目页（右页签）
        # messure_project_cofig == '' 表示"首次完整勾选/设置项目"
        # =========================
        if messure_project_cofig == '':
            # config_2 对应"测量项目页"的配置段
            config_2 = connect_messure_mode[6:]

            # 点击右页签（测量项目）
            pyautogui.moveTo(t2[0], t2[1], duration=0.5)
            pyautogui.click()

            # 先把项目区做一次清理/重置（通过批量点击固定坐标）
            if check_project_status == '':
                for i in range(len(cells_coord[0])):
                    pyautogui.moveTo(cells_coord[0][i][0] + left, cells_coord[0][i][1] + top, duration=0.5)
                    pyautogui.click()
                    check_project_status = '1'
            else:
                # 非首次时双击一次，尽量把状态拉回预期
                for i in range(len(cells_coord[0])):
                    pyautogui.moveTo(cells_coord[0][i][0] + left, cells_coord[0][i][1] + top, duration=0.5)
                    pyautogui.click()
                    pyautogui.sleep(1.0)
                    pyautogui.click()

            # i_list 是"谐波开始/结束"这类特殊下拉项在 config_2 里的索引
            if wt_type == 'WT3000':
                i_list = [38, 39]
            elif wt_type == 'WT1800' or wt_type == 'WT1806E':
                i_list = [59, 60]
            elif wt_type == 'WT5000':
                i_list = [65, 66]

            # 逐项应用 config_2
            _cells_detail = cells_coord[1] if cells_coord and len(cells_coord) > 1 else []
            for i in range(len(config_2)):
                if config_2[i] != '':
                    cell_idx = i + 6
                    if cell_idx >= len(_cells_detail):
                        _append_debug_log(
                            f"[messured_set][warn] skip config_2[{i}]={config_2[i]!r}, "
                            f"cells idx {cell_idx} out of range (len={len(_cells_detail)})"
                        )
                        continue
                    # 特殊下拉项：谐波开始/结束只能点下拉（顺序 Total/DC/1…50）
                    if i in i_list:
                        pyautogui.moveTo(_cells_detail[cell_idx][0] + left, _cells_detail[cell_idx][1] + top, duration=0.5)
                        pyautogui.doubleClick()
                        pyautogui.moveTo(_cells_detail[cell_idx][0] + left, _cells_detail[cell_idx][1] + top + 20, duration=0.5)
                        value = config_2[i]
                        value_key = str(value).strip()
                        alias = START_AND_STOP_ALIASES.get(value_key) or START_AND_STOP_ALIASES.get(
                            value_key.upper()
                        )
                        if alias:
                            if alias != value_key:
                                _append_debug_log(
                                    f"[messured_set] normalize START_AND_STOP '{value_key}' -> '{alias}'"
                                )
                            value_key = alias
                        if value_key not in START_AND_STOP_COORD:
                            _append_debug_log(
                                f"[messured_set][error] unknown START_AND_STOP key '{value}', "
                                f"use DC/1/50 (0→DC, 51→50)."
                            )
                            pyautogui.press('esc')
                            continue
                        if value_key == '50':
                            pyautogui.scroll(START_AND_STOP_COORD[value_key][0])
                            pyautogui.sleep(0.2)
                            pyautogui.scroll(START_AND_STOP_COORD[value_key][1])
                            pyautogui.sleep(0.2)
                            pyautogui.click()
                        else:
                            offset = START_AND_STOP_COORD[value_key][1]
                            pyautogui.moveTo(
                                _cells_detail[cell_idx][0] + left,
                                _cells_detail[cell_idx][1] + top + offset, duration=0.5)
                            pyautogui.click()
                        _append_debug_log(
                            f"[messured_set] START_AND_STOP dropdown '{value_key}'"
                        )
                    else:
                        # 普通项目：直接点击勾选
                        pyautogui.moveTo(_cells_detail[cell_idx][0] + left, _cells_detail[cell_idx][1] + top, duration=0.5)
                        pyautogui.click()

            # 标记：测量项目页首次配置已完成
            messure_project_cofig = '1'
        
        # =========================
        # 第三部分：非首次场景的"局部更新"
        # 当 messsure_deatil_cofig == '0' 时，表示本轮只需更新部分参数
        # =========================
        if messsure_deatil_cofig == '0':
            # 过欠压/过欠频：每轮测试时长可能不同，这里按 now_save_file 动态改时分秒
            if test_program[0][0] == '7' or test_program[0][0] == '11':
                test_time_now = float(per_test_time_list[now_save_file])
                m, s = divmod(test_time_now, 60)
                h, m = divmod(m, 60)
                test_time_list = [int(h), int(m), int(s)]
                for local in range(len(cells_coord[1][2])):
                    pyautogui.moveTo(cells_coord[1][2][local][0] + left, cells_coord[1][2][local][1] + top, duration=0.5)
                    pyautogui.doubleClick()
                    pyautogui.typewrite(str(test_time_list[local]))
                    pyautogui.sleep(0.2)
            else:
                # 下一段配置已经写了新的 StopTime。只改文件名时 WT 仍停在上一段时长，
                # 新段更长就会被仪器提前停表。
                stop_raw = ""
                try:
                    if isinstance(config_dict, dict):
                        stop_raw = config_dict.get("textEdit_StopTime") or ""
                except Exception:
                    stop_raw = ""
                hms = _parse_stoptime_to_hms(stop_raw)
                if hms is not None:
                    test_time_list = [int(hms[0]), int(hms[1]), int(hms[2])]
                    for local in range(min(len(test_time_list), len(cells_coord[1][2]))):
                        pyautogui.moveTo(
                            cells_coord[1][2][local][0] + left,
                            cells_coord[1][2][local][1] + top,
                            duration=0.5,
                        )
                        pyautogui.doubleClick()
                        pyautogui.typewrite(str(test_time_list[local]))
                        pyautogui.sleep(0.2)
                    _append_debug_log(
                        f"[messured_set] partial StopTime={stop_raw!r} -> {test_time_list}"
                    )

            # 自动保存开启时，每轮更新当前文件名
            if auto_save_file == '0':
                pyautogui.moveTo(cells_coord[1][5][0] + left, cells_coord[1][5][1] + top, duration=0.5)
                pyautogui.click()
                pyautogui.hotkey('ctrl', 'a', interval=0.5)
                pyperclip.copy(save_file_name)
                pyautogui.hotkey('ctrl', 'V', interval=0.5)

            # 本轮局部更新完成
            messsure_deatil_cofig = '1'

    # 详细页+项目页都就绪后，点击"确认/应用"提交配置
    if  messure_project_cofig == '1' and messsure_deatil_cofig == '1':
        parm_dict_set = {}
        win32gui.EnumChildWindows(deatil_messure_set_handle, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), parm_dict_set)
        # 不同语言/版本按钮文案可能是 确认 / 应用 / 确定
        _confirm_btn = None
        for _btn_text in ('确认', '应用', '确定', 'OK', 'Ok'):
            if _btn_text in parm_dict_set.values():
                _confirm_btn = list(parm_dict_set.keys())[list(parm_dict_set.values()).index(_btn_text)]
                _append_debug_log(f"[messured_set] click confirm button text={_btn_text!r}")
                break
        if _confirm_btn is not None:
            left, top, right, bottom = win32gui.GetWindowRect(_confirm_btn)
            pyautogui.moveTo(left + (right - left) / 2, top + (bottom - top) / 2, duration=0.5)
            pyautogui.click()
            # 等待 WT 应用配置完成
            pyautogui.sleep(10)
        else:
            _append_debug_log(
                f"[messured_set][error] no confirm/apply button found, "
                f"child_texts={list(parm_dict_set.values())}"
            )

        # 标记：测量配置整体完成，可进入后续测量流程
        messure_status = '1'

def _append_debug_log(message):
    """将关键调试信息追加到项目根目录 log.txt。"""
    try:
        with open('log.txt', 'a', encoding='utf-8') as f:
            f.write(f"{now_to_datenow()} {message}\n")
    except Exception as e:
        logger.warning(f"写入log.txt失败: {e}")


def _refresh_wt_measure_filename():
    """同一局的下一段录波：打开数值详细设置，只改文件名。"""
    global messure_handle_now
    now_handle_dict = get_enumwindows()
    now_h = _find_wtviewer_hwnd(now_handle_dict)
    if now_h is None:
        raise RuntimeError("WTViewerEfree window not found")
    _close_wt_detail_dialogs()
    win32gui.ShowWindow(now_h, win32con.SW_SHOWMAXIMIZED)
    win32gui.SetForegroundWindow(now_h)
    now_child_dict = {}
    win32gui.EnumChildWindows(
        now_h,
        lambda hwnd, parm: parm.update({hwnd: win32gui.GetWindowText(hwnd)}),
        now_child_dict,
    )
    if "数值" not in now_child_dict.values():
        raise RuntimeError("数值 control not found")
    messure_handle_now = list(now_child_dict.keys())[
        list(now_child_dict.values()).index("数值")
    ]
    # messsure_deatil_cofig=='0' 且测量项已勾过时，messured_set 只贴文件名。
    messured_set(messure_handle_now)


def messure_testing():
    """
    周期性测量调度器（每 0.5 秒自触发一次）。

    主要职责：
    1) 检查 WT 是否已经完成"可开始测量"的前置状态。
    2) 计算本轮测量应持续的时间（兼容过欠压/过欠频特殊逻辑）。
    3) 调用 testing_start() 启动测量，等待到时后调用 testing_stop() 收尾。
    4) 通过状态位控制"每轮测量后需要重新下发详细配置"。

    关键状态位：
    - setting_status == '1'：设置页（接线方式/更新率）已配置完成。
    - messure_status == '1'：数值详细设置页已配置完成。
    - WT_auto_messure_status == '1'：允许本轮自动测量触发（触发后会被清空，防止重复触发）。

    重要：本函数在任意异常或分支后都必须继续 0.5s 自调度，否则 run_loop 会永久卡在
    "等待 col7 测量结束 (test_status=0)"，表现成"已触发测量但不点 WT 开始、不再往下走"。
    """
    global test_time_list, messsure_deatil_cofig, config_dict, messure_status, setting_status, WT_auto_messure_status
    global now_save_file, total_save_file, volt_fz_first_status, per_test_time_list, test_program
    global test_status, save_file_name, strTestStatusFlag
    global _wt_async_stop_requested, _wt_async_deadline_ts, _wt_async_session_active
    global _wt_measure_flow_entered, _wt_gather_start_wall

    # 仅在关键状态变化时记录日志，避免定时器每 0.5 秒刷屏
    current_state = (setting_status, messure_status, WT_auto_messure_status, now_save_file, total_save_file)
    last_state = getattr(messure_testing, '_last_state', None)
    if current_state != last_state:
        _append_debug_log(
            f"[messure_testing] state changed setting_status={setting_status}, messure_status={messure_status}, "
            f"WT_auto_messure_status={WT_auto_messure_status}, now_save_file={now_save_file}, total_save_file={total_save_file}"
        )
        messure_testing._last_state = current_state

    try:
        # 只有"三个门闩"都满足时才进入本轮自动测量
        if setting_status == '1' and messure_status == '1' and WT_auto_messure_status == '1':
            _append_debug_log("[messure_testing] enter measure flow")
            _wt_measure_flow_entered = True
            # Soft Panel 真正点开始后再刷新；SCPI 路径以 collector._gather_start 为准
            _wt_gather_start_wall = time.time()
            # 进门后立即清空触发位，避免定时器下一拍重复进入同一轮
            WT_auto_messure_status = ''
            # 置位"测量进行中"，供 run_loop(col6/col7) 阻塞等待
            test_status = '1'

            # SCPI 命令模式：不点 WTViewer，直接 :RATE + NUMERIC 采数
            try:
                from utils.wt_acquire_mode import is_scpi_mode
                from utils import wt_scpi_session
            except Exception:
                is_scpi_mode = lambda *_a, **_k: False  # noqa: E731
                wt_scpi_session = None
            if is_scpi_mode(config_dict if isinstance(config_dict, dict) else {}):
                _append_debug_log("[messure_testing] SCPI acquire path")
                try:
                    if ui is not None:
                        ui.textEdit_ReturnMessage.append("[功率分析仪] SCPI 采集中…")
                except Exception:
                    pass
                ok = False
                released = {"done": False}

                def _release_wait_end_for_export():
                    # 停采后先放行 WAIT_END，慢导出不堵关机命令
                    global test_status, WT_auto_messure_status
                    global _wt_async_stop_requested, _wt_async_deadline_ts
                    if released["done"]:
                        return
                    released["done"] = True
                    test_status = "0"
                    WT_auto_messure_status = ""
                    _wt_async_stop_requested = False
                    _wt_async_deadline_ts = 0.0
                    _append_debug_log(
                        "[messure_testing] SCPI release WAIT_END before export"
                    )

                if wt_scpi_session is not None:
                    ok = wt_scpi_session.run_measure_blocking(
                        config_dict if isinstance(config_dict, dict) else {},
                        file_index=max(0, int(now_save_file or 0)),
                        stop_event_check=lambda: globals().get("strTestStatusFlag") == "结束",
                        async_stop_check=lambda: bool(
                            globals().get("_wt_async_stop_requested")
                        ),
                        on_stopped=_release_wait_end_for_export,
                        logger=logger,
                    )
                if ok:
                    csv_path = wt_scpi_session.last_csv() if wt_scpi_session else ""
                    _append_debug_log(f"[messure_testing] SCPI done csv={csv_path}")
                    try:
                        if ui is not None and csv_path:
                            ui.textEdit_ReturnMessage.append(
                                f"[功率分析仪] SCPI 已导出: {csv_path}"
                            )
                    except Exception:
                        pass
                else:
                    err = (
                        wt_scpi_session.last_error()
                        if wt_scpi_session
                        else "SCPI session unavailable"
                    )
                    _append_debug_log(f"[messure_testing][error] SCPI measure failed: {err}")
                    try:
                        if ui is not None:
                            ui.textEdit_ReturnMessage.append(
                                f"[功率分析仪] SCPI 采集失败: {err}"
                            )
                    except Exception:
                        pass
                _release_wait_end_for_export()
                messsure_deatil_cofig = ''
                return

            # 解析待保存文件名列表（支持英文逗号/中文逗号）
            # 示例："case1,case2，case3" -> ["case1", "case2", "case3"]
            test_count = re.split(',|，', config_dict['textEdit_FileNameList'])
            _append_debug_log(f"[messure_testing] file list={test_count}")
            if len(test_count) != total_save_file:
                _append_debug_log(
                    f"[messure_testing][warn] file_list_count({len(test_count)}) != total_save_file({total_save_file})"
                )
            if len(test_count) == 0 or (
                len(test_count) == 1 and not str(test_count[0] or "").strip()
            ):
                _append_debug_log(
                    "[messure_testing][error] empty file list, skip this round (WT trigger consumed; check UI filename list)"
                )
                # 必须放行 run_loop，否则会卡在第16条 [AC] query *IDN? 空等
                test_status = "0"
                WT_auto_messure_status = ""
            else:
                # 计算 loop_time（单位：0.1 秒）
                # 原因：后面用 for + sleep(0.1) 计时，因此秒数要乘以 10
                stop_raw = ""
                # 优先用 Append 写入的 config_dict.StopTime（过欠压分开录已同步为扫点驻留）。
                # 旧分支走 test_time_list 常残留 Soft Panel 00:05:00，首点空等 5 分钟（job112）。
                _use_cfg_stop = bool(_wt_async_session_active)
                try:
                    if isinstance(config_dict, dict):
                        stop_raw = config_dict.get("textEdit_StopTime") or ""
                except Exception:
                    stop_raw = ""
                loop_from_cfg = _stoptime_to_loop_01s(stop_raw, fallback_hms=None)
                if loop_from_cfg is not None and loop_from_cfg > 0:
                    loop_time = loop_from_cfg
                    if volt_fz_first_status == 0 and (
                        not test_program
                        or test_program[0][0] in ("7", "11")
                    ):
                        volt_fz_first_status = 1
                elif not _use_cfg_stop and test_program and (
                    test_program[0][0] == "7" or test_program[0][0] == "11"
                ):
                    # 无同步 StopTime 时的旧兜底
                    if volt_fz_first_status == 0:
                        loop_time = int(
                            test_time_list[0] * 3600
                            + test_time_list[1] * 60
                            + test_time_list[2]
                        ) * 10
                        volt_fz_first_status = 1
                    else:
                        try:
                            loop_time = int(per_test_time_list[now_save_file]) * 10
                        except Exception:
                            loop_time = int(
                                test_time_list[0] * 3600
                                + test_time_list[1] * 60
                                + test_time_list[2]
                            ) * 10
                else:
                    loop_time = _stoptime_to_loop_01s(stop_raw, fallback_hms=test_time_list)
                    if loop_time is None:
                        loop_time = int(
                            test_time_list[0] * 3600
                            + test_time_list[1] * 60
                            + test_time_list[2]
                        ) * 10
                    if _use_cfg_stop and volt_fz_first_status == 0 and test_program and (
                        test_program[0][0] == "7" or test_program[0][0] == "11"
                    ):
                        volt_fz_first_status = 1

                _append_debug_log(
                    f"[messure_testing] computed loop_time={loop_time} (0.1s unit), "
                    f"StopTime={stop_raw!r}, async={_use_cfg_stop}"
                )

                # 发起"开始测量"动作（点击 WT 的开始按钮）
                # 与当前索引对齐文件名，避免首轮出现空文件名
                if now_save_file < 0 or now_save_file >= len(test_count):
                    clamped_index = max(0, min(now_save_file, len(test_count) - 1))
                    _append_debug_log(
                        f"[messure_testing][warn] index out of range: now_save_file={now_save_file}, "
                        f"clamped_to={clamped_index}, file_count={len(test_count)}"
                    )
                    now_save_file = clamped_index
                save_file_name = test_count[now_save_file]
                # 同一次运行里的下一段配置：详细页只改文件名，不再整页重勾测量项。
                if messsure_deatil_cofig == '0':
                    try:
                        _refresh_wt_measure_filename()
                    except Exception as _fn_exc:
                        _append_debug_log(
                            f"[messure_testing][warn] refresh filename skipped: {_fn_exc}"
                        )
                try:
                    status = testing_start()
                except Exception as e:
                    _append_debug_log(f"[messure_testing][error] testing_start exception: {e}")
                    logger.exception("messure_testing: testing_start")
                    status = '0'
                    messsure_deatil_cofig = '0'
                    messure_status = '0'
                    test_status = '0'

                if status == '1':
                    current_name = test_count[now_save_file] if now_save_file < len(test_count) else f"INDEX_{now_save_file}"
                    _append_debug_log(f"[messure_testing] testing_start success, current_file={current_name}, index={now_save_file}")
                    # Soft Panel 点开始成功：绝对时间锚点
                    _wt_gather_start_wall = time.time()
                    try:
                        _set_run_progress_round(now_save_file, "进行中", note=f"测量中: {current_name}")
                    except Exception:
                        pass
                    # 成功开始后，按 loop_time 等待；结束试验 / 连续录 WAIT_END / 截止时刻应立刻停表
                    aborted = False
                    early_stop = False
                    waited_ticks = 0
                    for j in range(loop_time):
                        waited_ticks = j
                        if strTestStatusFlag == "结束":
                            aborted = True
                            _append_debug_log(
                                f"[messure_testing] aborted by EndProject during wait "
                                f"({j}/{loop_time})"
                            )
                            break
                        if _wt_async_stop_requested:
                            early_stop = True
                            _append_debug_log(
                                f"[messure_testing] stop requested during continuous wait "
                                f"({j}/{loop_time})"
                            )
                            break
                        if _wt_async_deadline_ts and time.time() >= _wt_async_deadline_ts:
                            early_stop = True
                            _append_debug_log(
                                f"[messure_testing] async deadline reached during wait "
                                f"({j}/{loop_time})"
                            )
                            break
                        if strTestStatusFlag == "暂停":
                            time.sleep(0.1)
                            continue
                        time.sleep(0.1)
                    else:
                        waited_ticks = loop_time
                    if early_stop and waited_ticks <= 1:
                        # Soft Panel 几乎未采点就 testing_stop，常落成 header+1 行 CSV
                        try:
                            ui_obj = globals().get("ui")
                            if ui_obj is not None:
                                ui_obj.textEdit_ReturnMessage.append(
                                    "[功率分析仪] 连续录几乎未采点即停表，CSV 可能只有 1 帧，"
                                    "请检查 ASYNC/WAIT_END 间距与 Soft Panel 连接"
                                )
                        except Exception:
                            pass
                        _append_debug_log(
                            f"[messure_testing][warn] early_stop at tick={waited_ticks}/"
                            f"{loop_time} — expect short CSV"
                        )

                    # 标记：下一轮进入前需要重新写入详细参数（如文件名/时间）
                    messsure_deatil_cofig = '0'
                    # 标记：当前轮已结束，等待后续流程重新置为 '1'
                    messure_status = '0'

                    # 先放行 WAIT_END，再去做 Soft Panel 停表存盘。
                    # 连续录自然跑满 StopTime 时也会卡在 testing_stop（点停/存盘），
                    # 若不先清 test_status，WAIT_END 会空等 12s 再「强制收口」。
                    release_before_stop = bool(
                        aborted or early_stop or _wt_async_session_active
                    )
                    if release_before_stop:
                        test_status = '0'
                        WT_auto_messure_status = ''
                        _wt_async_stop_requested = False
                        _wt_async_deadline_ts = 0.0
                        _append_debug_log(
                            f"[messure_testing] release WAIT_END before testing_stop "
                            f"aborted={aborted} early_stop={early_stop} "
                            f"async={_wt_async_session_active}"
                        )

                    # 停止测量 + 保存处理 + 决定是否进入下一轮
                    _append_debug_log(
                        f"[messure_testing] call testing_stop, aborted={aborted}, "
                        f"early_stop={early_stop}, "
                        f"current_index={now_save_file}, current_file={current_name}"
                    )
                    try:
                        testing_stop(test_count, now_save_file)
                    except Exception as e:
                        # 若抛错不调度下次 Timer，会导致测量线程链永久断掉
                        _append_debug_log(f"[messure_testing][error] testing_stop exception: {e}")
                        logger.exception("messure_testing: testing_stop")
                        messsure_deatil_cofig = '0'
                        messure_status = '0'
                        test_status = '0'
                    else:
                        if not release_before_stop:
                            test_status = '0'
                else:
                    _append_debug_log("[messure_testing] testing_start failed, set status to reconfigure")
                    # 启动失败时同样把状态置回"待重配"，让后续流程有机会恢复
                    messsure_deatil_cofig = '0'
                    messure_status = '0'
                    # 释放 run_loop 的 col6/col7 等待
                    test_status = '0'
    except Exception as e:
        _append_debug_log(f"[messure_testing][error] unexpected: {e}")
        logger.exception("messure_testing")
        messure_status = '0'
        messsure_deatil_cofig = '0'
        test_status = '0'
    finally:
        # 自循环定时器：0.5 秒后再次检查（**必须**执行，不能因 return/异常而漏掉）
        messure_test = threading.Timer(0.5, messure_testing)
        messure_test.start()

def _merge_wt_round_csv_if_needed(round_label):
    """静态Cos等项目：把本轮 WT CSV 追加进单一合并文件，并删除分轮文件。"""
    global config_dict
    try:
        cfg = config_dict if isinstance(config_dict, dict) else {}
    except NameError:
        return
    if str(cfg.get("wt_merge_single_file", "")).strip() not in ("1", "true", "True", "YES", "yes"):
        return
    merge_path = str(cfg.get("wt_merge_output_path") or "").strip()
    if not merge_path:
        return
    round_label = (round_label or "").strip() or "UNKNOWN"
    from utils.wt_csv_merge import append_round_to_merge, candidate_save_dirs, find_wt_csv
    search_dirs = candidate_save_dirs(
        cfg.get("textEdit_SavePath") or "",
        extra=[os.path.dirname(merge_path), os.path.abspath("."), os.getcwd()],
    )
    # 停测后稍等落盘
    src = find_wt_csv(round_label, search_dirs, wait_s=3.0)
    if not src:
        _append_debug_log(f"[wt_merge] source not found for round={round_label}, dirs={search_dirs}")
        try:
            ui.textEdit_ReturnMessage.append(f"[合并CSV] 未找到本轮文件: {round_label}")
        except Exception:
            pass
        return
    try:
        n = append_round_to_merge(merge_path, src, round_label, delete_source=True)
        _append_debug_log(f"[wt_merge] appended {n} rows from {src} -> {merge_path}")
        try:
            ui.textEdit_ReturnMessage.append(
                f"[合并CSV] {round_label}: +{n} 行 → {os.path.basename(merge_path)}"
            )
        except Exception:
            pass
    except Exception as e:
        _append_debug_log(f"[wt_merge][error] {e}")
        logger.exception("wt_merge")


def testing_stop(test_count, count_now):
    global save_file_name, messsure_deatil_cofig, test_status, total_save_file
    global setting_status, messure_status, messsure_deatil_cofig, messure_project_cofig
    global integral_status
    _append_debug_log(f"[testing_stop] enter count_now={count_now}, total_save_file={total_save_file}, file_list={test_count}")

    if messsure_deatil_cofig == '0' and auto_save_file == '0':
        now_child_dict = {}
        now_handle_dict = {}
        now_handle_dict = get_enumwindows()
        now_h = _find_wtviewer_hwnd(now_handle_dict)
        if now_h is None:
            _append_debug_log("[testing_stop][error] WTViewerEfree window not found")
            # 找不到 Soft Panel 也必须放行 run_loop，否则卡在 *IDN?/WAIT_END
            test_status = '0'
            return
        win32gui.ShowWindow(now_h, win32con.SW_SHOWMAXIMIZED)
        win32gui.SetForegroundWindow(now_h)
        pyautogui.moveTo(messure_icon[0], messure_icon[1], duration=0.1)
        pyautogui.click()
        
        left, top, right, bottom = win32gui.GetWindowRect(now_h)
        # 鼠标移动至停止按钮并点击
        pyautogui.moveTo(left + 626, top + 98, duration= 0.1)
        pyautogui.click()
        # Soft Panel 异步落盘：稍等再 merge / 回填 Freq*-SIGMA
        pyautogui.sleep(0.8)
        # 本轮刚停下：立刻并入合并 CSV（静态 Cos 等开启 wt_merge_single_file 时）
        try:
            _round = ""
            if isinstance(test_count, (list, tuple)) and 0 <= int(count_now) < len(test_count):
                _round = str(test_count[int(count_now)]).strip()
            if not _round:
                _round = str(globals().get("save_file_name") or "").strip()
            _merge_wt_round_csv_if_needed(_round)
            # Soft Panel：回填空 Freq*-SIGMA，并写入 Abs Time（对齐德威创）
            try:
                from utils.wt_csv_merge import candidate_save_dirs
                from utils.wt_csv_sigma_fill import fill_recent_csvs_in_dirs
                from utils.wt_csv_abs_time import inject_abs_time_in_dirs

                _cfg = config_dict if isinstance(config_dict, dict) else {}
                _dirs = candidate_save_dirs(
                    _cfg.get("textEdit_SavePath") or "",
                    extra=[os.path.abspath("."), os.getcwd()],
                )
                _wall = float(globals().get("_wt_gather_start_wall") or 0.0)
                # 没记到开录时刻时，只看停录前 90 秒内的文件，避免扫到上一轮 QCap
                _floor = _wall if _wall > 0 else (time.time() - 90.0)
                _filled = []
                for _ in range(5):
                    _filled = fill_recent_csvs_in_dirs(
                        _dirs, name_hint=_round, limit=1, min_mtime=_floor
                    )
                    if _filled:
                        break
                    time.sleep(0.4)
                if _filled:
                    _append_debug_log(
                        f"[testing_stop] filled empty Freq*-SIGMA in: {_filled}"
                    )
                if _wall > 0:
                    _absed = inject_abs_time_in_dirs(
                        _dirs, _wall, name_hint=_round, limit=1, min_mtime=_floor
                    )
                    if _absed:
                        _append_debug_log(
                            f"[testing_stop] injected Abs Time in: {_absed}"
                        )
            except Exception as _sig_exc:
                _append_debug_log(f"[testing_stop][warn] sigma/abs fill skipped: {_sig_exc}")
        except Exception as e:
            _append_debug_log(f"[testing_stop][warn] merge hook failed: {e}")
        
        if integral_status == '1':
            # 积分结束-->积分复位-->
            pyautogui.moveTo(
                left + INTEGRAL_COORD['integral_stop'][0],
                top + INTEGRAL_COORD['integral_stop'][1],
                duration= 0.2)
            pyautogui.doubleClick()
            pyautogui.sleep(0.2)

            pyautogui.moveTo(
                left + INTEGRAL_COORD['integral_reset'][0],
                top + INTEGRAL_COORD['integral_reset'][1],
                duration= 0.1)
            pyautogui.doubleClick()
            pyautogui.sleep(1)
        # 停止后需要重新打开"数值详细设置"来写入下一轮参数。
        # 但 WT 在连续运行/窗口焦点切换后，"数值"子控件可能短暂不存在或标题不完全一致，
        # 这里做重试和兼容匹配，避免 ValueError 直接把定时线程打崩。
        messure_handle_now = None
        last_children_snapshot = None
        for attempt in range(1, 6):
            now_child_dict = {}
            win32gui.EnumChildWindows(
                now_h,
                lambda hwnd, parm: parm.update({hwnd: win32gui.GetWindowText(hwnd)}),
                now_child_dict
            )
            child_titles = list(now_child_dict.values())
            last_children_snapshot = child_titles

            # 1) 精确匹配
            if '数值' in child_titles:
                messure_handle_now = list(now_child_dict.keys())[child_titles.index('数值')]
                break
            # 2) 兼容：包含"数值"的标题（例如"数值列表"等）
            for idx, title in enumerate(child_titles):
                if isinstance(title, str) and ('数值' in title):
                    messure_handle_now = list(now_child_dict.keys())[idx]
                    break
            if messure_handle_now is not None:
                break

            _append_debug_log(
                f"[testing_stop][warn] WT child not ready (attempt {attempt}/5): "
                f"'数值' not found, children_count={len(child_titles)}"
            )
            # 尝试重新点一次"测量/数值"页签，让控件重新出现
            try:
                pyautogui.moveTo(messure_icon[0], messure_icon[1], duration=0.1)
                pyautogui.click()
            except Exception:
                pass
            pyautogui.sleep(0.2)

        if messure_handle_now is None:
            _append_debug_log(
                f"[testing_stop][error] WT child '数值' still not found after retries. "
                f"children_sample={last_children_snapshot[:20] if last_children_snapshot else []}"
            )
            # 兜底：至少释放 run_loop 的等待，避免整条自动化卡死
            test_status = '0'
            # 并把 WT 配置状态打回未就绪，让后续流程重新走配置/恢复
            setting_status = ''
            messure_status = ''
            messsure_deatil_cofig = ''
            messure_project_cofig = ''
            return
    
        # 1) 整单录完。后面还有别的试验（例如静态 QU 之后的动态 QU）时走 2)，
        #    不能因为文件名列表只剩 1 个就把整单收掉。
        from utils.wt_recording_stop import decide_wt_recording_stop

        n_names = len(test_count) if isinstance(test_count, (list, tuple)) else 0
        try:
            n_prog = len(test_program) if isinstance(test_program, (list, tuple)) else 0
        except Exception:
            n_prog = 0
        _stop_decision = decide_wt_recording_stop(
            count_now=count_now,
            total_save_file=total_save_file,
            name_count=n_names,
            program_count=n_prog,
        )
        _append_debug_log(
            f"[testing_stop] decision={_stop_decision} count_now={count_now} "
            f"total_save_file={total_save_file} names={n_names} programs={n_prog}"
        )
        if _stop_decision == "all_done":
            print('测试结束')
            _append_debug_log(
                f"[testing_stop] all tests finished "
                f"(count_now={count_now}, total_save_file={total_save_file}, names={n_names})"
            )
            try:
                _set_run_progress_round(count_now, "完成", note="本轮完成")
            except Exception:
                pass
            try:
                cfg = config_dict if isinstance(config_dict, dict) else {}
                mp = str(cfg.get("wt_merge_output_path") or "").strip()
                if mp and str(cfg.get("wt_merge_single_file", "")).strip() in ("1", "true", "True", "YES", "yes"):
                    ui.textEdit_ReturnMessage.append(f"[合并CSV] 整次试验合并完成: {mp}")
            except Exception:
                pass
            # 置位为已配置，防止后续误触发重新配置
            messsure_deatil_cofig = '1'
            # 当前轮结束
            test_status = '0'

        # 2) 当前"项目"结束，但后面还有其它项目：
        #    清空 WT 配置状态，让下一个项目重新走 auto_config / messured_set
        elif _stop_decision == "project_done":
            print('此项目测试结束')
            _append_debug_log("[testing_stop] current project finished, reset WT config status for next project")
            try:
                _set_run_progress_round(count_now, "完成", note="本项目完成")
            except Exception:
                pass
            test_status = '0'
            setting_status = '' 
            messure_status = ''
            messsure_deatil_cofig = ''
            messure_project_cofig = ''

        # 3) 当前项目未结束：进入下一轮文件名
        else:
            # 未结束时进入下一轮，应当由当前索引推进到下一索引。
            # 加边界保护，避免异常情况下写出 INDEX_x 越界文件名。
            try:
                _set_run_progress_round(count_now, "完成", note="本轮完成")
            except Exception:
                pass
            next_index = max(0, min(count_now + 1, len(test_count) - 1))
            save_file_name = test_count[next_index]
            _append_debug_log(
                f"[testing_stop] next round transition index {count_now}->{next_index}, "
                f"file={save_file_name}, total={len(test_count)}"
            )
            # 重新打开"数值详细设置"并写入下一轮参数（主要是文件名/时长）
            messured_set(messure_handle_now)
            # 标记"详细设置"已完成
            messsure_deatil_cofig = '1'
            # 当前轮结束，等待下次调度进入 testing_start
            test_status = '0'

def testing_start():
    """
    作用：启动 WT 一轮测量。

    主要动作：
    - 校验 WT 配置状态是否就绪
    - 切到测量页并点击"开始"
    - 若开启积分，则先点积分开始
    - 若弹出"文件已存在，是否覆盖"对话框，自动点"是"

    返回：
    - '1'：已成功触发开始测量（或完成覆盖确认）
    """
    global save_file_name, messsure_deatil_cofig, integral_status

    # 首轮触发时 testing_stop 尚未给 save_file_name 赋值，先兜底避免 NameError
    if 'save_file_name' not in globals():
        save_file_name = ''

    _append_debug_log(f"[testing_start] enter setting_status={setting_status}, messure_status={messure_status}, save_file_name={save_file_name}")

    # 只有"设置页已配置 + 数值页已配置"时，才允许开始测量
    if setting_status == '1' and messure_status == '1':
        now_handle_dict = {}
        now_child_dict = {}

        # 1) 获取 WT 主窗口句柄
        now_handle_dict = get_enumwindows()
        now_h = _find_wtviewer_hwnd(now_handle_dict)
        if now_h is None:
            _append_debug_log("[testing_start][error] WTViewerEfree window not found")
            return False

        # 2) 窗口最大化并置前，避免点击打到其他窗口
        win32gui.ShowWindow(now_h, win32con.SW_SHOWMAXIMIZED)
        win32gui.SetForegroundWindow(now_h)

        # 3) 点击左侧"测量/数值"图标，确保当前页面在测量页
        pyautogui.moveTo(messure_icon[0], messure_icon[1], duration=0.1)
        pyautogui.click()

        # 获取窗口矩形，用于后续相对坐标点击
        left, top, right, bottom = win32gui.GetWindowRect(now_h)

        # 4) 若启用积分功能，先执行"积分开始"
        if integral_status == '1':
            pyautogui.moveTo(
                left + INTEGRAL_COORD['integral_start'][0],
                top + INTEGRAL_COORD['integral_start'][1],
                duration= 0.1)
            pyautogui.doubleClick()
            pyautogui.sleep(0.5)

        # 5) 点击测量"开始"按钮（固定相对坐标）
        pyautogui.moveTo(left + 586, top + 98, duration= 0.1)
        pyautogui.click()
        pyautogui.sleep(0.2)

        # 6) 检查是否出现"重名文件覆盖"弹窗
        #    逻辑：检测到"是(&Y)"和"否(&N)"按钮即视为覆盖确认框
        now_handle_dict = get_enumwindows()
        now_h = _find_wtviewer_hwnd(now_handle_dict)
        if now_h is None:
            _append_debug_log("[testing_start][error] WTViewerEfree window lost after start click")
            return False
        win32gui.EnumChildWindows(now_h, lambda hwnd, parm: parm.update({hwnd:win32gui.GetWindowText(hwnd)}), now_child_dict)
        if '是(&Y)' in now_child_dict.values() and '否(&N)' in now_child_dict.values():
            _append_debug_log(f"[testing_start] overwrite dialog detected for file={save_file_name}, choose YES")
            handle_sure = list(now_child_dict.keys())[list(now_child_dict.values()).index('是(&Y)')]
            left_warn, top_warn, right_warn, bottom_warn = win32gui.GetWindowRect(handle_sure)
            # 默认选择"是"，允许覆盖旧文件并继续流程
            pyautogui.moveTo(left_warn + (right_warn - left_warn) / 2, top_warn + (bottom_warn - top_warn) / 2, duration=0.5)
            pyautogui.click()

        _append_debug_log(f"[testing_start] started file={save_file_name}")
        # 启动动作完成
        return '1'

