def _should_poll_equ_ctrl_for_syst_err(ctrl, connect_btn):
    """句柄已丢但 UI 仍为「已连接」时也要轮询：open_resource 失败后 connected=False 时不能永久跳过。"""
    if ctrl is None:
        return False
    if ctrl.connected:
        return True
    if not (getattr(ctrl, "resource", "") or "").strip():
        return False
    try:
        return connect_btn.text() == "取消连接"
    except Exception:
        return False


def _startup_auto_connect_last_devices() -> None:
    """兼容旧调用：改为异步启动，避免堵死 UI。"""
    _schedule_startup_auto_connect(visa_rm=None)


def _schedule_startup_auto_connect(*, visa_rm=None) -> None:
    """后台：VISA 列表 + 准备连接任务；主线程：按槽位排队连接（不长时间卡界面）。"""
    from PyQt5.QtCore import QObject, QTimer, pyqtSignal

    try:
        ui.textEdit_ReturnMessage.append("[启动] 后台准备自动连接（界面可继续操作）…")
    except Exception:
        pass

    parent = QtWidgets.QApplication.instance()
    class _BootBridge(QObject):
        prepared = pyqtSignal(object, object, object)  # equ_list, jobs, devices

    bridge = _BootBridge(parent)
    try:
        # Keep alive until boot finishes (local refs can be GC'd)
        ui._startup_boot_bridge = bridge
    except Exception:
        pass

    def _on_prepared(equ_list, jobs, devices):
        global EQUList
        try:
            if equ_list:
                EQUList = list(equ_list)
                _publish_scanned_equ_list(EQUList)
            elif not EQUList:
                EQUList = ["未发现可连接设备"]
        except Exception:
            EQUList = ["未发现可连接设备"]
        print(f"[DEBUG_STARTUP]    boot equ={EQUList!r} jobs={len(jobs or [])}", flush=True)
        _run_startup_connect_jobs_stepwise(list(jobs or []), list(devices or []))

    bridge.prepared.connect(_on_prepared)

    def _worker():
        equ_list = []
        jobs = []
        devices = []
        try:
            _rm = visa_rm
            if _rm is None:
                # 多数工控机 RM 1～3s 内就绪；15s 空等会让「启动自动连」体感很慢
                _rm = _wait_visa_rm_boot(timeout_s=6.0)
            if _rm is None:
                try:
                    _rm = rm
                except Exception:
                    _rm = None
            if _rm is not None:
                try:
                    globals()["rm"] = _rm
                except Exception:
                    pass
                try:
                    from app.context import get_app_context

                    _ctx = get_app_context()
                    if _ctx is not None:
                        _ctx.rm = _rm
                except Exception:
                    pass
                try:
                    str1 = _rm.list_resources()
                    equ_list = list(str1) if str1 else []
                except Exception as exc:
                    print(f"[DEBUG_STARTUP]    boot list_resources fail: {exc}", flush=True)
            from utils.iot_auto_connect import prepare_auto_connect_jobs

            _status_path = os.path.join(
                os.path.dirname(os.path.abspath(__file__)), "status.json"
            )
            # 启动一律跳过德威创：台架常残留 dew IP/status，自动重连失败会弹窗；
            # 真要用时在 Soft Panel 点连接，或 IOT 勾选 radio_dewetron 再由 handoff 连。
            jobs, devices = prepare_auto_connect_jobs(
                visa_rm=_rm,
                status_json_path=_status_path,
                scan_lan=False,
                skip_slots=("dew",),
            )
        except Exception as exc:
            print(f"[DEBUG_STARTUP]    boot prepare fail: {exc}", flush=True)
            jobs, devices = [], []
        try:
            bridge.prepared.emit(equ_list, jobs, devices)
        except Exception as exc:
            print(f"[DEBUG_STARTUP]    boot emit fail: {exc}", flush=True)

    import threading

    threading.Thread(target=_worker, name="startup-auto-connect", daemon=True).start()


def _run_startup_connect_jobs_stepwise(jobs, devices) -> None:
    """主线程逐个槽位连接，槽位之间让出事件循环，避免一打开卡死数秒。"""
    from PyQt5.QtCore import QTimer

    state = {
        "i": 0,
        "connected": [],
        "errors": [],
        "found": len(devices or []),
        "jobs": jobs or [],
    }

    def _log(msg: str) -> None:
        try:
            ui.textEdit_ReturnMessage.append(f"[启动自动连] {msg}")
        except Exception:
            print(f"[启动自动连] {msg}", flush=True)

    if not state["jobs"]:
        try:
            ui.textEdit_ReturnMessage.append(
                f"[启动] 自动连接完成：无可连任务（发现 {state['found']}）"
            )
        except Exception:
            pass
        return

    try:
        ui.textEdit_ReturnMessage.append(
            f"[启动] 开始按槽位连接（共 {len(state['jobs'])}），请稍候…"
        )
    except Exception:
        pass

    def _step() -> None:
        jobs_local = state["jobs"]
        i = state["i"]
        if i >= len(jobs_local):
            try:
                _reconcile_status_json_with_sessions()
            except Exception:
                pass
            msg = (
                f"[启动] 自动连接完成：成功 {len(state['connected'])}，"
                f"失败 {len(state['errors'])}，发现 {state['found']}"
            )
            try:
                ui.textEdit_ReturnMessage.append(msg)
                for e in state["errors"][:8]:
                    ui.textEdit_ReturnMessage.append(f"[启动自动连] {e}")
            except Exception:
                print(msg, flush=True)
            return

        slot, plan, dev = jobs_local[i]
        state["i"] = i + 1
        try:
            _apply_device_finder_plan(slot, plan, dev)
            if _iot_slot_session_ok(slot):
                try:
                    from utils.iot_auto_connect import remember_slot_for_resource

                    remember_slot_for_resource(getattr(dev, "resource", "") or "", slot)
                except Exception:
                    pass
                state["connected"].append(f"{slot}:{getattr(dev, 'resource', '')}")
                _log(f"自动连接 {slot} -> {getattr(dev, 'resource', '')}")
            else:
                target = str((plan or {}).get("target") or "")
                resource = str(getattr(dev, "resource", "") or "")
                host = str(getattr(dev, "host", "") or "")
                port = getattr(dev, "port", None)
                res_u = resource.upper()
                if res_u.startswith(("USB", "ASRL", "GPIB", "COM", "TCPIP")):
                    where = resource
                elif host and port is not None:
                    where = f"{host}:{port}"
                else:
                    where = resource or host
                hint = f"{target}@{where}" if target else where
                err = f"{slot}: 桌面连接失败（会话未建立；{hint}）"
                state["errors"].append(err)
                _log(f"自动连接失败 {slot}: 会话未建立 {hint}")
        except Exception as exc:
            state["errors"].append(f"{slot}: {exc}")
            _log(f"自动连接失败 {slot}: {exc}")

        # Yield so clicks/paint still work between device connects
        QTimer.singleShot(50, _step)

    QTimer.singleShot(0, _step)


def system_error_info():
    """周期性轮询设备系统错误并尝试重连；并纠偏 status.json（对齐 Java list 轮询在线）。"""
    global ac_controller
    _reconcile_ticks = 0
    while True:
        # 主线程正在连接/刷新接口时让出，避免与 open_resource / *IDN? 抢同一句柄
        if _is_device_ui_busy():
            time.sleep(0.25)
            continue
        # 约每 5 秒按真实会话纠偏 status.json（试验运行中也要写，否则网页 WT 一直「未连接」）
        _reconcile_ticks += 1
        if _reconcile_ticks >= 5:
            _reconcile_ticks = 0
            try:
                _reconcile_status_json_with_sessions()
            except Exception:
                pass
        # 试验运行中不要 SYST:ERR?/自动重连，避免与 RunProject 抢同一句柄
        try:
            if "strTestStatusFlag" in globals() and strTestStatusFlag in ("运行", "暂停"):
                time.sleep(1.0)
                continue
        except Exception:
            pass
        if _should_poll_equ_ctrl_for_syst_err(ac_controller, ui.pushButton_ConnectEQUAC):
            # Modbus TCP（ModbusVISA）：句柄为 SOCKET，不支持 SCPI SYST:ERR?；勿用下拉框原文 open_resource（含中文会触发 PyVISA ascii 错误）
            if ac_controller.client is not None:
                time.sleep(1)
            else:
                information_AC = ''
                try:
                    information_AC = ac_controller.handle.query("SYST:ERR?")
                    time.sleep(1)
                except Exception as e:
                    print(e)
                    logger.error(e)
                    tcp_addr = _normalize_equ_resource_text(ui.comboBox_AC.currentText())
                    try:
                        # Chroma IP / ScpiSocket：必须用原生 TCP 重连。
                        # 若误走 rm.open_resource(TCPIP0::ip::INSTR)，会得到坏 VISA 会话，
                        # 上电时报 VI_ERROR_INV_RSRC_NAME（Parsing error / invalid character）。
                        prefer_socket = (
                            ac_controller.uses_scpi_socket()
                            or str(getattr(ac_controller, "resource", "") or "").startswith("TCPIP::")
                            or globals().get("_ac_current_brand") == "chroma_ip"
                            or str(tcp_addr).upper().startswith("TCPIP")
                        )
                        host, port = ACController._parse_scpi_tcp_endpoint(
                            tcp_addr, getattr(ac_controller, "resource", "")
                        )
                        if prefer_socket and host:
                            ac_controller.reconnect_scpi_tcp(host, port)
                        else:
                            endpoint = _split_ipv4_tcp_endpoint(tcp_addr)
                            if endpoint is not None:
                                host, port = endpoint
                                _safe_close_handle(ac_controller.handle)
                                ac_controller.client = None
                                ac_controller._itech = None
                                ac_controller._set_handle(None)
                                client = ModbusVISA(
                                    host,
                                    port,
                                    on_session_renewed=ac_controller._set_handle,
                                    use_plain_socket=True,
                                )
                                client.connect()
                                if client.is_connected():
                                    ac_controller.client = client
                                    ac_controller._set_handle(client.inst or client)
                                    ac_controller._itech = ItechTranslator(client)
                                    ac_controller.resource = f'{host}:{port}'
                                    print(f'AC---reconnect(modbus)---{ac_controller.handle}')
                                    logger.info(f'AC---reconnect(modbus)---{ac_controller.handle}')
                                else:
                                    ac_controller.client = None
                                    ac_controller._itech = None
                                    ac_controller._set_handle(None)
                            else:
                                # USB/GPIB 等：必须先释放旧 VISA 会话再 open，否则常出现 VI_ERROR_SYSTEM_ERROR 且反复重连无效
                                _safe_close_handle(ac_controller.handle)
                                ac_controller._set_handle(None)
                                time.sleep(0.12)
                                handle = rm.open_resource(tcp_addr)
                                try:
                                    _configure_scpi_resource(handle)
                                except Exception:
                                    release_resource_handle(handle)
                                    raise
                                ac_controller.client = None
                                ac_controller._itech = None
                                ac_controller._set_handle(handle)
                                ac_controller.resource = tcp_addr
                                print(f'AC---reconnect---{ac_controller.handle}')
                                logger.info(f'AC---reconnect---{ac_controller.handle}')
                    except Exception as e2:
                        logger.error(e2)
                        print(e2)
                    time.sleep(2)
                else:
                    logger.info(f'AC return error message: {information_AC}')
        
        if _should_poll_equ_ctrl_for_syst_err(dc1_controller, ui.pushButton_ConnectEQUDC1):
            tcp_addr_dc1 = _normalize_equ_resource_text(ui.comboBox_DC1.currentText())
            _, information_DC1 = dc1_controller.poll_syst_err(tcp_addr_dc1, 'DC1')
            if information_DC1 is not None:
                logger.info(f'DC1 return error message: {information_DC1}')
        
        if _should_poll_equ_ctrl_for_syst_err(dc2_controller, ui.pushButton_ConnectEQUDC2):
            tcp_addr_dc2 = _normalize_equ_resource_text(ui.comboBox_DC2.currentText())
            _, information_DC2 = dc2_controller.poll_syst_err(tcp_addr_dc2, 'DC2')
            if information_DC2 is not None:
                logger.info(f'DC2 return error message: {information_DC2}')
        
        if _should_poll_equ_ctrl_for_syst_err(dc3_controller, ui.pushButton_ConnectEQUDC3):
            tcp_addr_dc3 = _normalize_equ_resource_text(ui.comboBox_DC3.currentText())
            _, information_DC3 = dc3_controller.poll_syst_err(tcp_addr_dc3, 'DC3')
            if information_DC3 is not None:
                logger.info(f'DC3 return error message: {information_DC3}')
        
        if _should_poll_equ_ctrl_for_syst_err(dc4_controller, ui.pushButton_ConnectEQUDC4):
            tcp_addr_dc4 = _normalize_equ_resource_text(ui.comboBox_DC4.currentText())
            _, information_DC4 = dc4_controller.poll_syst_err(tcp_addr_dc4, 'DC4')
            if information_DC4 is not None:
                logger.info(f'DC4 return error message: {information_DC4}')
        
        time.sleep(33.33)


