            def _stop_iot_agent_on_exit():
                """关主界面 / 退出进程时同步停掉 Agent，避免仍 WS 上线显示待机。"""
                try:
                    import os

                    from utils.status_json_devices import persist_queue_cleared_for_closed_app

                    _status = os.path.join(
                        os.path.dirname(os.path.abspath(__file__)), "status.json"
                    )
                    persist_queue_cleared_for_closed_app(_status)
                except Exception as _q_exc:
                    print(f"[IOT-Agent] 退出清队列失败: {_q_exc}", flush=True)
                try:
                    if isinstance(_run_progress_state, dict):
                        _run_progress_state["queue"] = []
                        if str(_run_progress_state.get("status") or "") in (
                            "进行中",
                            "暂停",
                            "待开始",
                        ):
                            _run_progress_state["status"] = "已中止"
                            _run_progress_state["operator_pause"] = False
                except Exception:
                    pass
                try:
                    from agent.process_control import clear_gui_pid, stop_agent_for_app_exit

                    clear_gui_pid()
                    _ok, msg = stop_agent_for_app_exit()
                    print(f"[IOT-Agent] 退出同步停止: {msg}", flush=True)
                except Exception as _e:
                    print(f"[IOT-Agent] 退出停止异常: {_e}", flush=True)
                    try:
                        from agent.process_control import stop_agent

                        stop_agent()
                    except Exception:
                        pass

            def _auto_start_iot_agent():
                """网络 announce/claim 放到后台线程，避免启动后白屏卡顿。"""
                from PyQt5.QtCore import QObject, pyqtSignal

                class _BootBridge(QObject):
                    finished = pyqtSignal(str)

                bridge = _BootBridge(main_window)

                def _on_done(msg: str):
                    try:
                        ui.textEdit_ReturnMessage.append(f"[IOT-Agent] {msg}")
                    except Exception:
                        print(f"[IOT-Agent] {msg}", flush=True)
                    _refresh_iot_agent_status()

                bridge.finished.connect(_on_done)

                def _worker():
                    msg = ""
                    try:
                        from agent.process_control import ensure_agent_running

                        _ok, msg = ensure_agent_running(silent=True)
                    except Exception as _e:
                        msg = f"自动启动异常: {_e}"
                    try:
                        bridge.finished.emit(str(msg or ""))
                    except Exception:
                        print(f"[IOT-Agent] {msg}", flush=True)

                import threading

                threading.Thread(target=_worker, name="iot-agent-boot", daemon=True).start()

