            def _deferred_polish_and_db():
                """分片 polish，避免一次扫全树卡顿；DB 进后台线程。"""
                from PyQt5.QtCore import QTimer as _QT

                def _polish_main():
                    try:
                        from utils.ui_field_helpers import polish_input_widgets

                        _n = polish_input_widgets(main_window)
                        print(
                            f"[DEBUG_STARTUP]    deferred polish main done (~{_n})",
                            flush=True,
                        )
                    except Exception as _polish_exc:
                        print(
                            f"[DEBUG_STARTUP]    deferred polish main fail: {_polish_exc}",
                            flush=True,
                        )
                    _QT.singleShot(50, _polish_extras)

                def _polish_extras():
                    try:
                        from utils.ui_field_helpers import polish_input_widgets

                        _wt3000_page = ui.stackedWidget.widget(7)
                        for _extra in getattr(
                            _wt3000_page, "_extra_widgets_comboBox_WT3000", {}
                        ).values():
                            polish_input_widgets(_extra)
                        try:
                            from utils.wt_channel_scale import load_saved_scales

                            # 只从配置档回填到输入框；不自动写档、不自动下发仪器
                            _saved_scales = load_saved_scales()
                            for _name, _text in (_saved_scales or {}).items():
                                _edit = getattr(ui, _name, None)
                                if _edit is not None and hasattr(_edit, "setText"):
                                    _edit.setText(str(_text))
                        except Exception as _scale_exc:
                            print(f"[WT] 回填比例系数失败: {_scale_exc}")
                        for _name in (
                            "uiACSetting",
                            "uiDC1Setting",
                            "uiDC2Setting",
                            "uiDC3Setting",
                            "uiDC4Setting",
                            "uiDL850Setting",
                            "uiDewetronSetting",
                        ):
                            _f = globals().get(_name)
                            if _f is None:
                                continue
                            try:
                                for _attr in dir(_f):
                                    if _attr.startswith(
                                        ("textEdit_", "lineEdit_", "comboBox_")
                                    ) or _attr in ("combo_phase",):
                                        _w = getattr(_f, _attr, None)
                                        if _w is not None:
                                            polish_input_widgets(_w)
                            except Exception as _pe:
                                print(f"[UI] polish skip {_name}: {_pe}", flush=True)
                        _itch = globals().get("_ac_itch_ref") or {}
                        _phase_w = _itch.get("combo_phase") if isinstance(_itch, dict) else None
                        if _phase_w is not None:
                            polish_input_widgets(_phase_w)
                        print("[DEBUG_STARTUP]    deferred polish extras done", flush=True)
                    except Exception as _polish_exc:
                        print(
                            f"[DEBUG_STARTUP]    deferred polish extras fail: {_polish_exc}",
                            flush=True,
                        )

                def _db_worker():
                    try:
                        print("[DEBUG_STARTUP]    deferred init DEWETRON database...", flush=True)
                        init_database()
                    except Exception as _db_exc:
                        print(
                            f"[DEBUG_STARTUP]    deferred init_database fail: {_db_exc}",
                            flush=True,
                        )

                _QT.singleShot(0, _polish_main)
                threading.Thread(
                    target=_db_worker, name="startup-init-db", daemon=True
                ).start()

            # 打开软件后：VISA 扫描 + 准备任务在后台；连接按槽位排队，不堵界面
            try:
                from PyQt5.QtCore import QTimer

                QTimer.singleShot(300, _deferred_polish_and_db)
                # 不传本地闭包 rm（可能仍为 None）；后台线程自己等 RM boot
                QTimer.singleShot(500, lambda: _schedule_startup_auto_connect(visa_rm=None))
                # 默认不预热全部试验页（工控机会卡死）；仅 SOLARAUTOTEST_PRELOAD=1 时启用
                def _kick_auto_test_preload():
                    import os as _os_kick

                    if str(_os_kick.environ.get("SOLARAUTOTEST_PRELOAD", "")).strip().lower() not in (
                        "1",
                        "true",
                        "yes",
                        "on",
                    ):
                        print(
                            "[DEBUG_STARTUP] Auto_Test preload not scheduled "
                            "(on-demand only)",
                            flush=True,
                        )
                        return
                    _fn = getattr(ui, "_preload_auto_test_pages", None)
                    if callable(_fn):
                        _fn()

                QTimer.singleShot(1200, _kick_auto_test_preload)
            except Exception as _ac_exc:
                print(f"[DEBUG_STARTUP]    启动自动连接调度失败: {_ac_exc}", flush=True)
            # IOT 云任务 handoff：监视 pending → Append/开始 → 等结束写 results
