                def _iot_get_run_status():
                    """交接读状态：内存终态可能是上一单，优先认 status.json 的待开始/进行中。"""
                    try:
                        mem = str((_run_progress_state or {}).get("status") or "").strip()
                        if mem in ("已结束", "已中止", "失败", "中止", ""):
                            try:
                                import json
                                from pathlib import Path

                                path = Path(__file__).resolve().parent / "status.json"
                                raw = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
                                proj = raw.get("project") if isinstance(raw, dict) else {}
                                file_st = str((proj or {}).get("status") or "").strip()
                                if file_st in ("待开始", "未开始", "进行中", "暂停"):
                                    return file_st
                            except Exception:
                                pass
                        return mem
                    except Exception:
                        return ""

                def _iot_get_run_progress():
                    try:
                        st = _run_progress_state or {}
                        detail = str(st.get("current_detail") or "").strip()
                        status = str(st.get("status") or "")
                        remain = str(st.get("remain_text") or "").strip()
                        cur = str(st.get("current_test") or "").strip()
                        qn = len(st.get("queue") or [])
                        cmd_index = int(st.get("cmd_index") or 0)
                        cmd_total = int(st.get("cmd_total") or 0)
                        parts = [x for x in (status, cur, remain, detail) if x]
                        if qn:
                            parts.append(f"共{qn}项")
                        if cmd_total > 0:
                            parts.append(f"命令 {cmd_index}/{cmd_total}")
                        if st.get("operator_pause"):
                            parts.append("等人工改逆变器后点继续试验")
                        text = " | ".join(parts).strip()
                        step = (detail or cur or status or "running")[:128]
                        return {
                            "percent": int(st.get("progress") or 0),
                            "text": (text or "进行中")[:255],
                            "step": step,
                            "cmd_index": cmd_index,
                            "cmd_total": cmd_total,
                        }
                    except Exception:
                        return {"percent": 0, "text": "", "step": "", "cmd_index": 0, "cmd_total": 0}

                def _iot_ensure_project(name: str):
                    try:
                        if hasattr(ui, "comboBox_PS") and name:
                            idx = ui.comboBox_PS.findText(str(name))
                            if idx >= 0:
                                ui.comboBox_PS.setCurrentIndex(idx)
                            else:
                                ui.comboBox_PS.setCurrentText(str(name))
                    except Exception as exc:
                        print(f"[IOT交接] 切换项目失败: {exc}", flush=True)

                def _iot_auto_connect():
                    from utils.iot_auto_connect import auto_connect_best_effort
                    import os

                    status_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "status.json")
                    return auto_connect_best_effort(
                        apply_plan=_apply_device_finder_plan,
                        visa_rm=globals().get("rm"),
                        status_json_path=status_path,
                        log=_iot_log,
                    )

                def _iot_prepare_auto_connect():
                    from utils.iot_auto_connect import prepare_auto_connect_jobs
                    import os

                    status_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "status.json")
                    # IOT 开测默认不自动连德威创；要连时由云端 instruments + job_wants_dewetron 显式带上
                    return prepare_auto_connect_jobs(
                        visa_rm=globals().get("rm"),
                        status_json_path=status_path,
                        scan_lan=False,
                        skip_slots=("dew",),
                    )

                def _iot_apply_auto_connect(prepared):
                    from utils.iot_auto_connect import apply_prepared_connect_jobs

                    jobs, devices = prepared if isinstance(prepared, tuple) else (prepared, [])
                    summary = apply_prepared_connect_jobs(
                        jobs,
                        apply_plan=_apply_device_finder_plan,
                        log=_iot_log,
                        session_ok=_iot_slot_session_ok,
                    )
                    summary["found"] = len(devices) if devices is not None else summary.get("found", 0)
                    summary["skipped_ambiguous"] = max(
                        0, int(summary.get("found") or 0) - int(summary.get("attempted") or 0)
                    )
                    return summary

                def _iot_ensure_ready(ui_obj, test_type):
                    from utils.iot_device_ready import (
                        check_devices_ready,
                        format_ready_fail_reason,
                        required_dc_slots_from_ui,
                    )
                    from utils.iot_output_limits import (
                        evaluate_controllers_output_limits_gate,
                        map_per_dc_factor_to_brands,
                    )

                    slots = required_dc_slots_from_ui(ui_obj)
                    dc_controllers = {
                        "dc1": globals().get("dc1_controller"),
                        "dc2": globals().get("dc2_controller"),
                        "dc3": globals().get("dc3_controller"),
                        "dc4": globals().get("dc4_controller"),
                    }
                    ok, reasons = check_devices_ready(
                        ac_controller=globals().get("ac_controller"),
                        dc_controllers=dc_controllers,
                        per_dc_factor=globals().get("per_dc_factor") or {},
                        required_dc_slots=slots,
                        require_ac=True,
                    )
                    if not ok:
                        return ok, format_ready_fail_reason(reasons)

                    # 勾了功率分析仪 / WT 模式却未连上时，不能因 AC/DC 已连就跳过云端扫连
                    try:
                        s2 = getattr(ui_obj, "checkBox_S2", None)
                        need_wt = bool(s2 is not None and s2.isChecked())
                        if not need_wt:
                            for rn in ("radio_wt3000", "radio_wt", "radioButton_WT3000"):
                                radio = getattr(ui_obj, rn, None)
                                if radio is not None and radio.isChecked():
                                    need_wt = True
                                    break
                        if not need_wt:
                            section = getattr(ui_obj, "analyzerModeSection", None)
                            if section is not None and hasattr(section, "is_wt"):
                                need_wt = bool(section.is_wt())
                    except Exception:
                        need_wt = False
                    if need_wt and not _iot_slot_session_ok("wt"):
                        return False, "功率分析仪未连接"

                    try:
                        dew_mode = False
                        section = getattr(ui_obj, "analyzerModeSection", None)
                        if section is not None and hasattr(section, "is_dewetron"):
                            dew_mode = bool(section.is_dewetron())
                        if not dew_mode:
                            radio = getattr(ui_obj, "radioButton_DEWETRON", None) or getattr(
                                ui_obj, "radio_dewetron", None
                            )
                            if radio is not None and radio.isChecked():
                                dew_mode = True
                        if dew_mode and not _iot_slot_session_ok("dew"):
                            return False, "德威创未连接"
                    except Exception:
                        pass

                    ok_lim, reason_lim = evaluate_controllers_output_limits_gate(
                        ac_controller=globals().get("ac_controller"),
                        dc_controllers=dc_controllers,
                        ac_brand=globals().get("_ac_current_brand"),
                        dc_brands=map_per_dc_factor_to_brands(
                            globals().get("per_dc_factor")
                        ),
                    )
                    if not ok_lim:
                        return False, reason_lim
                    return True, ""

